begin;
    with j as (select * from jsonb_to_recordset($law7v001$[{"code_id":"APK_RF","article_number":"1","version_date":"2002-07-24","article_text":"Правосудие в сфере предпринимательской и иной экономической деятельности осуществляется арбитражными судами в Российской Федерации, образованными в соответствии с Конституцией Российской Федерации и федеральным конституционным законом (далее - арбитражные суды), путем разрешения экономических споров и рассмотрения иных дел, отнесенных к их компетенции Арбитражным процессуальным кодексом Российской Федерации и другими федеральными законами, по правилам, установленным законодательством о судопроизводстве в арбитражных судах.","article_title":"Статья 1. Осуществление правосудия арбитражными судами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51f0a54fc0f49a7f24159a26a4c89d0487254c3cc2c945c3a49327bbbbe79a66"},{"code_id":"APK_RF","article_number":"10","version_date":"2002-07-24","article_text":"1. Арбитражный суд при разбирательстве дела обязан непосредственно исследовать все доказательства по делу.\n\n2. Доказательства, которые не были предметом исследования в судебном заседании, не могут быть положены арбитражным судом в основу принимаемого судебного акта.","article_title":"Статья 10. Непосредственность судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d29a78eed47d3a8d898c7409ec3ff647c1d0f4b2d7964e0edbf372e814d49b1"},{"code_id":"APK_RF","article_number":"100","version_date":"2002-07-24","article_text":"Правила об обеспечении иска, предусмотренные настоящей главой, применяются при обеспечении исполнения судебных актов.","article_title":"Статья 100. Обеспечение исполнения судебных актов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64d7dd83a116270c6d052264a70746537bec2d6bc8d6d096f2cf1ed282422611"},{"code_id":"APK_RF","article_number":"101","version_date":"2002-07-24","article_text":"Судебные расходы состоят из государственной пошлины и судебных издержек, связанных с рассмотрением дела арбитражным судом.","article_title":"Статья 101. Состав судебных расходов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c6a156c79ca5e0ffca1d3aad14672e2b1d24fc9d7f64d7e4b5d318fffc546e8"},{"code_id":"APK_RF","article_number":"102","version_date":"2002-07-24","article_text":"Основания и порядок уплаты государственной пошлины, а также порядок предоставления отсрочки или рассрочки уплаты государственной пошлины устанавливаются в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n(Статья в редакции Федерального закона от 02.11.2004 № 127-ФЗ)","article_title":"Статья 102. Уплата государственной пошлины","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a15ef147f7654f4df0e8d2ce9fc45827758105698d55dbd88291d073a9b0a441"},{"code_id":"APK_RF","article_number":"103","version_date":"2002-07-24","article_text":"1. Цена иска определяется:\n\n1) по искам о взыскании денежных средств, исходя из взыскиваемой суммы;\n\n2) по искам о признании не подлежащим исполнению исполнительного или иного документа, по которому взыскание производится в бесспорном (безакцептном) порядке, исходя из оспариваемой денежной суммы;\n\n3) по искам об истребовании имущества, исходя из стоимости истребуемого имущества;\n\n4) по искам об истребовании земельного участка, исходя из стоимости земельного участка.\n\nВ цену иска включаются также указанные в исковом заявлении суммы неустойки (штраф, пени) и проценты.\n\nЦена иска, состоящего из нескольких самостоятельных требований, определяется суммой всех требований.\n\n2. По исковым заявлениям о признании права, в том числе права собственности, права пользования, права владения, права распоряжения, государственная пошлина уплачивается в размерах, установленных для исковых заявлений неимущественного характера.\n\n3. Цена иска указывается заявителем.\n\nВ случае неправильного указания заявителем цены иска она определяется арбитражным судом.","article_title":"Статья 103. Цена иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a69ed8e4908838a31c50e939e0d25663c6baea7801cb6dabd6efe80786e61d8c"},{"code_id":"APK_RF","article_number":"104","version_date":"2002-07-24","article_text":"Основания и порядок возврата или зачета государственной пошлины устанавливаются в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n(Статья в редакции Федерального закона от 02.11.2004 № 127-ФЗ)","article_title":"Статья 104. Основания и порядок возврата или зачета государственной пошлины","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4113e91650ed5086d3929256e70ae44b3755d79f380baee367695ce87507e24b"},{"code_id":"APK_RF","article_number":"105","version_date":"2002-07-24","article_text":"Льготы по уплате государственной пошлины предоставляются в случаях и порядке, которые установлены законодательством Российской Федерации о налогах и сборах.\n\n(Статья в редакции Федерального закона от 02.11.2004 № 127-ФЗ)","article_title":"Статья 105. Льготы по уплате государственной пошлины","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"291bf3860364f284ea68d36cf2715a0b6a281f87af835054b9c358f9c381e2bb"},{"code_id":"APK_RF","article_number":"106","version_date":"2002-07-24","article_text":"К судебным издержкам, связанным с рассмотрением дела в арбитражном суде, относятся денежные суммы, подлежащие выплате экспертам, специалистам, свидетелям, переводчикам, расходы, связанные с проведением осмотра доказательств на месте, расходы на оплату услуг адвокатов и иных лиц, оказывающих юридическую помощь (представителей), расходы юридического лица на уведомление о корпоративном споре в случае, если федеральным законом предусмотрена обязанность такого уведомления, и другие расходы, понесенные лицами, участвующими в деле, в связи с рассмотрением дела в арбитражном суде. (В редакции федеральных законов от 19.07.2009 № 205-ФЗ; от 08.12.2011 № 422-ФЗ)","article_title":"Статья 106. Судебные издержки","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d73b938dd7fda1208c11736b7bbdc8c50ab7f05fe2ce083a67d09352a9bf20cc"},{"code_id":"APK_RF","article_number":"107","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\nРазмер вознаграждения эксперту определяется судом по согласованию с лицами, участвующими в деле, и по соглашению с экспертом.\n\nРазмер вознаграждения переводчику определяется судом по соглашению с переводчиком.","article_title":"Статья 107. Денежные суммы, подлежащие выплате экспертам, специалистам, свидетелям и переводчикам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"007ec7a2ac7502269f5c9346e7ad984ca9a63defe1884a9a46046880d9a4b734"},{"code_id":"APK_RF","article_number":"108","version_date":"2002-07-24","article_text":"1. Денежные суммы, подлежащие выплате экспертам и свидетелям, вносятся на депозитный счет арбитражного суда лицом, заявившим соответствующее ходатайство, в срок, установленный арбитражным судом. Если указанное ходатайство заявлено обеими сторонами, требуемые денежные суммы вносятся сторонами на депозитный счет арбитражного суда в равных частях.\n\n2. В случае, если в установленный арбитражным судом срок на депозитный счет арбитражного суда не были внесены денежные суммы, подлежащие выплате экспертам и свидетелям, арбитражный суд вправе отклонить ходатайство о назначении экспертизы и вызове свидетелей, если дело может быть рассмотрено и решение принято на основании других представленных сторонами доказательств.","article_title":"Статья 108. Внесение сторонами денежных сумм, необходимых для оплаты судебных издержек","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f7d485099b4f3ff0fb31680e757a674e76f8b9621a2f1ec66b7d8b12d1031d5"},{"code_id":"APK_RF","article_number":"109","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\nоплате услуг переводчика за счет средств федерального бюджета не распространяется на возмещение расходов на оплату услуг переводчика, понесенных иностранными лицами и лицами без гражданства, если иное не предусмотрено международным договором Российской Федерации.","article_title":"Статья 109. Выплата денежных сумм, причитающихся экспертам, специалистам, свидетелям и переводчикам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4dfc7e582d9157f46379f4d58899ce154a6778146ca9fc6f1b8c8ad5d12b7e6"},{"code_id":"APK_RF","article_number":"11","version_date":"2002-07-24","article_text":"1. Разбирательство дел в арбитражных судах открытое.\n\n2. Разбирательство дела в закрытом судебном заседании допускается в случаях, если открытое разбирательство дела может привести к разглашению государственной тайны, в иных случаях, предусмотренных федеральным законом, а также при удовлетворении ходатайства лица, участвующего в деле и\n\nссылающегося на необходимость сохранения коммерческой, служебной или иной охраняемой законом тайны.\n\n3. Разглашение сведений, составляющих государственную, коммерческую, служебную или иную охраняемую законом тайну, влечет за собой ответственность, установленную федеральным законом.\n\n4. О разбирательстве дела в закрытом судебном заседании выносится определение. Определение выносится в отношении всего судебного разбирательства или его части.","article_title":"Статья 11. Гласность судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81d6045d93589a3c4f6bed9aa9bf3de20dd4ab198223d69025ee300d7ddba6bc"},{"code_id":"APK_RF","article_number":"110","version_date":"2002-07-24","article_text":"1. Судебные расходы, понесенные лицами, участвующими в деле, в пользу которых принят судебный акт, взыскиваются арбитражным судом со стороны.\n\nВ случае, если иск удовлетворен частично, судебные расходы относятся на лиц, участвующих в деле, пропорционально размеру удовлетворенных исковых требований.\n\n2. Расходы на оплату услуг представителя, понесенные лицом, в пользу которого принят судебный акт, взыскиваются арбитражным судом с другого лица, участвующего в деле, в разумных пределах.\n\n3. Государственная пошлина, от уплаты которой в установленном порядке истец был освобожден, взыскивается с ответчика в доход федерального бюджета пропорционально размеру удовлетворенных исковых требований, если ответчик не освобожден от уплаты государственной пошлины.\n\n4. При соглашении лиц, участвующих в деле, о распределении судебных расходов арбитражный суд относит на них судебные расходы в соответствии с этим соглашением.\n\n5. Судебные расходы, понесенные лицами, участвующими в деле, в связи с рассмотрением апелляционной, кассационной жалобы, распределяются по правилам, установленным настоящей статьей.","article_title":"Статья 110. Распределение судебных расходов между лицами, участвующими в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"990e7f57fda0196c1a167b855fb5165a9a88aa415aa94fa4278ab20a01b5d624"},{"code_id":"APK_RF","article_number":"111","version_date":"2002-07-24","article_text":"1. В случае, если спор возник вследствие нарушения лицом, участвующим в деле, претензионного или иного досудебного порядка урегулирования спора, предусмотренного федеральным законом или договором, в том числе нарушения срока представления ответа на претензию, оставления претензии без ответа, арбитражный суд относит на это лицо судебные расходы независимо от результатов рассмотрения дела.\n\n2. Арбитражный суд вправе отнести все судебные расходы по делу на лицо, злоупотребляющее своими процессуальными правами или не выполняющее своих процессуальных обязанностей, если это привело к срыву судебного заседания, затягиванию судебного процесса, воспрепятствованию рассмотрения дела и принятию законного и обоснованного судебного акта.\n\n3. По заявлению лица, участвующего в деле, на которое возлагается возмещение судебных расходов, арбитражный суд вправе уменьшить размер возмещения, если этим лицом представлены доказательства их чрезмерности.","article_title":"Статья 111. Отнесение судебных расходов на лицо, злоупотребляющее своими процессуальными правами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"34a877c696463f985b1f3558768c9f002a669ac860dac9bcb5527be7cd2ffcc4"},{"code_id":"APK_RF","article_number":"112","version_date":"2002-07-24","article_text":"1. Вопросы распределения судебных расходов, отнесения судебных расходов на лицо, злоупотребляющее своими процессуальными правами, и другие вопросы о судебных расходах разрешаются арбитражным судом соответствующей судебной инстанции в судебном акте, которым заканчивается рассмотрение дела по существу, или в определении.\n\nПропущенный по уважительной причине срок подачи такого заявления может быть восстановлен судом.\n\nЗаявление по вопросу о судебных расходах рассматривается по правилам, предусмотренным статьей 159 настоящего Кодекса, с учетом особенностей, установленных главой 29 настоящего Кодекса. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\nПо результатам рассмотрения такого заявления выносится определение, которое может быть обжаловано.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 112. Разрешение вопросов о судебных расходах","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed13fe069301da877ad44a6bae1483849a192a435b82bb1e2b85de69f0c96caa"},{"code_id":"APK_RF","article_number":"113","version_date":"2002-07-24","article_text":"1. Процессуальные действия совершаются в сроки, установленные настоящим Кодексом или иными федеральными законами, а в случаях, если процессуальные сроки не установлены, они назначаются арбитражным судом.\n\n2. Сроки совершения процессуальных действий определяются точной календарной датой, указанием на событие, которое обязательно должно наступить, или периодом, в течение которого действие может быть совершено.\n\n3. Процессуальные сроки исчисляются годами, месяцами и днями. В сроки, исчисляемые днями, не включаются нерабочие дни.\n\n4. Течение процессуального срока, исчисляемого годами, месяцами или днями, начинается на следующий день после календарной даты или дня наступления события, которыми определено начало процессуального срока.","article_title":"Статья 113. Установление и исчисление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1c8d3b6c4f3512427e3ab7b364731ca6af5586b12233cfe8694c83d42d714ade"},{"code_id":"APK_RF","article_number":"114","version_date":"2002-07-24","article_text":"1. Процессуальный срок, исчисляемый годами, истекает в соответствующий месяц и число последнего года установленного срока.\n\n2. Процессуальный срок, исчисляемый месяцами, истекает в соответствующее число последнего месяца установленного срока. Если окончание процессуального срока, исчисляемого месяцами, приходится на месяц, который соответствующего числа не имеет, срок истекает в последний день этого месяца.\n\n3. Процессуальный срок, исчисляемый днями, истекает в последний день установленного срока.\n\n4. В случаях, если последний день процессуального срока приходится на нерабочий день, днем окончания срока считается первый следующий за ним рабочий день.\n\n5. Процессуальное действие, для совершения которого установлен срок, может быть выполнено до двадцати четырех часов последнего дня установленного срока.\n\n6. Если заявление, жалоба, другие документы либо денежные суммы были сданы на почту, переданы или заявлены в орган либо уполномоченному их принять лицу до двадцати четырех часов последнего дня процессуального срока, срок не считается пропущенным.\n\n7. Если процессуальное действие должно быть совершено непосредственно в арбитражном суде или другой организации, срок истекает в тот час, когда в этом суде или этой организации по установленным правилам заканчивается рабочий день или прекращаются соответствующие операции.","article_title":"Статья 114. Окончание процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f0bc1eb1a788586e9e70dac7df350c5a9e71bce2f195e4dc5701262122237b85"},{"code_id":"APK_RF","article_number":"115","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, утрачивают право на совершение процессуальных действий с истечением процессуальных сроков, установленных настоящим Кодексом или иным федеральным законом либо арбитражным судом.\n\n2. Заявления, жалобы и другие поданные по истечении процессуальных сроков документы, если отсутствует ходатайство о восстановлении или продлении пропущенных сроков, не рассматриваются арбитражным судом и возвращаются лицам, которыми они были поданы.","article_title":"Статья 115. Последствия пропуска процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46064efc9ff9c81a932bbee1675b96476b9d3e331688625be60de4b832f21b9c"},{"code_id":"APK_RF","article_number":"116","version_date":"2002-07-24","article_text":"1. Течение всех неистекших процессуальных сроков приостанавливается одновременно с приостановлением производства по делу.\n\n2. Со дня возобновления производства по делу течение процессуальных сроков продолжается.","article_title":"Статья 116. Приостановление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93fad423fd8b1f6ce66d8921b8a66224dc9c70e0256a9a03ddfb618b1e983bfa"},{"code_id":"APK_RF","article_number":"117","version_date":"2002-07-24","article_text":"1. Процессуальный срок подлежит восстановлению по ходатайству лица, участвующего в деле, если иное не предусмотрено настоящим Кодексом.\n\nВосстановление пропущенного процессуального срока арбитражным судом указывается в соответствующем судебном акте.\n\nКопия определения направляется лицу, обратившемуся с ходатайством, не позднее следующего дня после дня вынесения определения.","article_title":"Статья 117. Восстановление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9ddb14e1b0ae14ddf89f0572ea5c8b11cd273a390eba46592d41dc6950d1d52c"},{"code_id":"APK_RF","article_number":"118","version_date":"2002-07-24","article_text":"1. Назначенные арбитражным судом процессуальные сроки могут быть им продлены по заявлению лица, участвующего в деле, по правилам, предусмотренным статьей 117 настоящего Кодекса.\n\n2. Определение арбитражного суда об отказе в продлении назначенного им процессуального срока может быть обжаловано.","article_title":"Статья 118. Продление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5318030a6eec505cf5c96425d851f47ebb7b1931486b54ce5f2b300d166d9a67"},{"code_id":"APK_RF","article_number":"119","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 119. Наложение судебных штрафов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bcd71eed48f3dded8dab96cc5f46af72c3c3961669f6f84d71b16cf3be1bf94b"},{"code_id":"APK_RF","article_number":"12","version_date":"2002-07-24","article_text":"1. Судопроизводство в арбитражном суде ведется на русском языке - государственном языке Российской Федерации.\n\n2. Лицам, участвующим в деле и не владеющим русским языком, арбитражный суд разъясняет и обеспечивает право знакомиться с материалами дела, участвовать в судебных действиях, выступать в суде на родном языке или свободно выбранном языке общения и пользоваться услугами переводчика.","article_title":"Статья 12. Язык судопроизводства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7c7cd197793fb2e12bbc3510e81ce2ef27555286977902473bcc8f8422058467"},{"code_id":"APK_RF","article_number":"120","version_date":"2002-07-24","article_text":"1. Вопрос о наложении судебного штрафа на лицо, присутствующее в судебном заседании, разрешается в том же судебном заседании арбитражного суда.\n\n2. Вопрос о наложении судебного штрафа на лицо, не присутствующее в судебном заседании, разрешается в другом судебном заседании арбитражного суда.\n\n3. Лицо, в отношении которого рассматривается вопрос о наложении судебного штрафа, извещается о времени и месте судебного заседания с указанием оснований проведения судебного заседания. Неявка надлежащим образом извещенного лица не является препятствием к рассмотрению вопроса о наложении судебного штрафа.\n\n4. По результатам рассмотрения вопроса о наложении судебного штрафа арбитражный суд выносит определение.\n\nКопия определения о наложении судебного штрафа направляется лицу, на которое наложен штраф, в пятидневный срок со дня вынесения определения.\n\n5. Определение о наложении судебного штрафа приводится в исполнение немедленно в порядке, установленном для исполнения решения арбитражного суда.\n\nИсполнительный лист направляется арбитражным судом судебному приставу-исполнителю по месту жительства или адресу лица, на которое наложен судебный штраф. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n6. Определение арбитражного суда о наложении судебного штрафа может быть обжаловано в десятидневный срок со дня получения лицом, на которое наложен судебный штраф, копии определения.\n\n7. Подача жалобы на определение о наложении судебного штрафа не приостанавливает исполнение определения.","article_title":"Статья 120. Порядок рассмотрения вопроса о наложении судебного штрафа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"351886b83fc62779064ff723f60a6d41e08cd9954cd1645eef51c88b1adeb854"},{"code_id":"APK_RF","article_number":"121","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, и иные участники арбитражного процесса извещаются арбитражным судом о принятии искового заявления или заявления к производству и возбуждении производства по делу, о времени и месте судебного заседания или совершения отдельного процессуального действия путем направления копии судебного акта в порядке, установленном настоящим Кодексом, не позднее чем за пятнадцать дней до начала судебного заседания или совершения отдельного процессуального действия, если иное не предусмотрено настоящим Кодексом.\n\nИнформация о принятии искового заявления или заявления к производству, о времени и месте судебного заседания или совершения отдельного процессуального действия размещается арбитражным судом в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее чем за пятнадцать дней до начала судебного заседания или совершения отдельного процессуального действия, если иное не предусмотрено настоящим Кодексом. Документы, подтверждающие размещение арбитражным судом в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" указанных сведений, включая дату их размещения, приобщаются к материалам дела. (В редакции федеральных законов от 11.07.2011 № 200-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n2. Судебный акт, которым извещаются или вызываются участники арбитражного процесса, должен содержать:\n\n1) наименование и адрес арбитражного суда, адрес официального сайта в информационно-телекоммуникационной сети \"Интернет\", на котором размещается информация о деятельности арбитражного суда, номера телефонов арбитражного суда, адреса электронной почты, по которым лица, участвующие в деле, могут получить информацию о рассматриваемом деле; (В редакции федеральных законов от 27.07.2010 № 228-ФЗ, от 11.07.2011 № 200-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n2) время и место судебного заседания или проведения отдельного процессуального действия;\n\n3) наименование лица, извещаемого или вызываемого в суд;\n\n4) наименование дела, по которому осуществляется извещение или вызов, а также указание, в качестве кого лицо вызывается;\n\n5) указание, какие действия и к какому сроку извещаемое или вызываемое лицо вправе или обязано совершить.\n\n3. В случаях, не терпящих отлагательства, арбитражный суд может известить или вызвать лиц, участвующих в деле, и иных участников арбитражного процесса телефонограммой, телеграммой, по факсимильной связи или электронной почте либо с использованием иных средств связи.\n\nСудебные извещения, адресованные гражданам, в том числе индивидуальным предпринимателям, направляются по месту их жительства. При этом место жительства индивидуального предпринимателя определяется на основании выписки из единого государственного реестра индивидуальных предпринимателей.\n\nЕсли лицо, участвующее в деле, ведет дело через представителя, судебное извещение направляется также по месту нахождения представителя.\n\nЕсли лицо, участвующее в деле, заявило ходатайство о направлении судебных извещений по иному адресу, арбитражный суд направляет судебное извещение также по этому адресу. В этом случае судебное извещение считается врученным лицу, участвующему в деле, если оно доставлено по указанному таким лицом адресу.\n\nСудебное извещение в электронном виде направляется участнику арбитражного процесса посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\nСудебное извещение по спору в отношении зарегистрированного результата интеллектуальной деятельности или средства индивидуализации направляется также по адресу для переписки, указанному в соответствующем государственном реестре. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nЛица, участвующие в деле, несут риск наступления неблагоприятных последствий в результате непринятия мер по получению информации о движении дела, если суд располагает информацией о том, что указанные лица надлежащим образом извещены о начавшемся процессе, за исключением случаев, когда лицами, участвующими в деле, меры по получению информации не могли быть приняты в силу чрезвычайных и непредотвратимых обстоятельств. (В редакции Федерального закона от 31.12.2014 № 527-ФЗ)\n\n(Дополнение частью - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 121. Судебные извещения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e5cf0fefa052d69baae17dcb6e73747105e26b20519d4de34ecf429f55423b9"},{"code_id":"APK_RF","article_number":"122","version_date":"2002-07-24","article_text":"1. Копия судебного акта направляется арбитражным судом по почте заказным письмом с уведомлением о вручении либо путем вручения адресату под расписку непосредственно в арбитражном суде или по месту нахождения адресата, а в случаях, не терпящих отлагательства, путем направления телефонограммы, телеграммы, по факсимильной связи или электронной почте либо с использованием иных средств связи.\n\nСудебный акт в электронном виде направляется участнику арбитражного процесса посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. Если арбитражный суд располагает доказательствами получения лицами, участвующими в деле, и иными участниками арбитражного процесса определения о принятии искового заявления или заявления к производству и возбуждении производства по делу, информации о времени и месте первого судебного заседания, судебные акты, которыми назначаются время и место последующих судебных заседаний или совершения отдельных процессуальных действий, направляются лицам, участвующим в деле, и иным участникам арбитражного процесса посредством размещения этих судебных актов в информационной системе, определенной Верховным Судом Российской Федерации, Судебным департаментом при Верховном Суде Российской Федерации, в разделе, доступ к которому предоставляется лицам, участвующим в деле, и иным участникам арбитражного процесса (далее также - в режиме ограниченного доступа). Арбитражный суд также вправе известить указанных лиц о последующих судебных заседаниях или совершении отдельных процессуальных действий по делу путем направления телефонограммы, телеграммы, по факсимильной связи или электронной почте либо с использованием иных средств связи. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n2. В случае, если копия судебного акта вручается адресату или его представителю непосредственно в арбитражном суде либо по месту их нахождения, такое вручение осуществляется под расписку.","article_title":"Статья 122. Порядок направления арбитражным судом копий судебных актов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e157b3ff76a53b1394f2292e5d45bb2d87337f8a70f7d9aef7ce726b66e44589"},{"code_id":"APK_RF","article_number":"123","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, и иные участники арбитражного процесса считаются извещенными надлежащим образом, если к началу судебного заседания, совершения отдельного процессуального действия арбитражный суд располагает сведениями о получении адресатом копии определения о принятии искового заявления или заявления к производству и возбуждении производства по делу, направленной ему в порядке, установленном настоящим Кодексом, или иными доказательствами получения лицами, участвующими в деле, информации о начавшемся судебном процессе.\n\n2. Гражданин считается извещенным надлежащим образом, если судебное извещение вручено ему лично или совершеннолетнему лицу, проживающему совместно с этим гражданином, под расписку на подлежащем возврату в арбитражный суд уведомлении о вручении либо ином документе с указанием даты и времени вручения, а также источника информации.\n\n3. Судебное извещение, адресованное юридическому лицу, вручается лицу, уполномоченному на получение корреспонденции.\n\n4. Лица, участвующие в деле, и иные участники арбитражного процесса также считаются извещенными надлежащим образом арбитражным судом, если:\n\n1) адресат отказался от получения копии судебного акта и этот отказ зафиксирован организацией почтовой связи или арбитражным судом;\n\n2) несмотря на почтовое извещение, адресат не явился за получением копии судебного акта, направленной арбитражным судом в установленном порядке, о чем организация почтовой связи уведомила арбитражный суд;\n\n3) копия судебного акта не вручена в связи с отсутствием адресата по указанному адресу, о чем организация почтовой связи уведомила арбитражный суд с указанием источника данной информации;\n\n4) судебное извещение вручено уполномоченному лицу филиала или представительства юридического лица;\n\n5) судебное извещение вручено представителю лица, участвующего в деле;\n\n6) имеются доказательства вручения или направления судебного извещения в порядке, установленном частями 2 и 3 статьи 122 настоящего Кодекса;\n\n7) имеется подтверждение доставки судебного извещения посредством единого портала государственных и муниципальных услуг участнику арбитражного процесса, давшему согласие на едином портале государственных и муниципальных услуг на уведомление его посредством единого портала государственных и муниципальных услуг, или доставки судебного извещения посредством системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение пунктом - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 123. Надлежащее извещение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ea53f7f23a9ecafd5baa1da9f76ff1517fc16d4fa001a8979c163e4e64291a7"},{"code_id":"APK_RF","article_number":"124","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, обязаны сообщить арбитражному суду об изменении своего наименования. При отсутствии такого сообщения лицо, участвующее в деле, именуется в судебном акте исходя из последнего известного арбитражному суду наименования этого лица.\n\n2. Лица, участвующие в деле, обязаны сообщить арбитражному суду об изменении своего адреса во время производства по делу. При отсутствии такого сообщения копии судебных актов направляются по последнему известному арбитражному суду адресу и считаются доставленными, хотя бы адресат по этому адресу более не находится или не проживает.\n\n3. В случае, если лицо, участвующее в деле, сообщало арбитражному суду номера телефонов и факсов, адрес электронной почты или аналогичную информацию, оно должно проинформировать арбитражный суд об их изменении во время производства по делу.\n\n4. Арбитражный суд указывает в определении или протоколе судебного заседания изменение наименования лица, участвующего в деле, его адреса, номеров телефонов и факсов, адреса электронной почты или аналогичной информации.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)\n\nРАЗДЕЛ II. ПРОИЗВОДСТВО В АРБИТРАЖНОМ СУДЕ ПЕРВОЙ ИНСТАНЦИИ. ИСКОВОЕ ПРОИЗВОДСТВО","article_title":"Статья 124. Изменение наименования лица, перемена адреса во время производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0eb59e04278baa1c3d742aef7160acd4b3ba72c2580007916bc8695310d2cc1f"},{"code_id":"APK_RF","article_number":"125","version_date":"2002-07-24","article_text":"1. Исковое заявление подается в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. Исковое заявление подписывается истцом или его представителем.\n\nИсковое заявление, подаваемое в электронном виде, содержащее ходатайство об обеспечении иска, должно быть подписано усиленной квалифицированной электронной подписью.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В исковом заявлении должны быть указаны:\n\n1) наименование арбитражного суда, в который подается исковое заявление;\n\n2) сведения об истце: для гражданина - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы или дата и место государственной регистрации в качестве индивидуального предпринимателя и один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения), номера телефонов, факсов, адреса электронной почты; для организации - наименование, адрес, идентификационный номер налогоплательщика, номера телефонов, факсов, адреса электронной почты; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n3) сведения об ответчике: для гражданина - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно) и один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер. В случае, если гражданину неизвестны дата и место рождения ответчика, один из его идентификаторов, об этом указывается в исковом заявлении и такая информация по запросу арбитражного суда предоставляется органами Фонда пенсионного и социального страхования Российской Федерации, и (или) налоговыми органами, и (или) органами внутренних дел. В этом случае срок принятия искового заявления к производству арбитражного суда, предусмотренный частью 1 статьи 127 настоящего Кодекса, исчисляется со дня получения арбитражным судом такой информации; (В редакции  федеральных законов от 21.12.2021 № 417-ФЗ, от 28.12.2022 № 569-ФЗ)\n\n4) требования истца к ответчику со ссылкой на законы и иные нормативные правовые акты, а при предъявлении иска к нескольким ответчикам - требования к каждому из них;\n\n5) обстоятельства, на которых основаны исковые требования, и подтверждающие эти обстоятельства доказательства;\n\n6) цена иска, если иск подлежит оценке;\n\n7) расчет взыскиваемой или оспариваемой денежной суммы;\n\n8) сведения о соблюдении истцом претензионного или иного досудебного порядка; (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n81) сведения о предпринятых стороной (сторонами) действиях, направленных на примирение, если такие действия предпринимались; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n9) сведения о мерах, принятых арбитражным судом по обеспечению имущественных интересов до предъявления иска;\n\n10) перечень прилагаемых документов.\n\nВ заявлении должны быть указаны и иные сведения, если они необходимы для правильного и своевременного рассмотрения дела, могут содержаться ходатайства, в том числе ходатайства об истребовании доказательств от ответчика или других лиц. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 125. Форма и содержание искового заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"66da65bf5d0f0c06198671cc0f8eefc05f27b456743d70b621c75cd2954f1bfe"},{"code_id":"APK_RF","article_number":"126","version_date":"2002-07-24","article_text":"1) уведомление о вручении или иные документы, подтверждающие направление другим лицам, участвующим в деле, копий искового заявления и приложенных к нему документов, которые у других лиц, участвующих в деле, отсутствуют, в том числе в случае подачи в суд искового заявления и приложенных к нему документов в электронном виде; (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2) документ, подтверждающий уплату государственной пошлины в установленных порядке и в размере или право на получение льготы по уплате государственной пошлины, либо ходатайство о предоставлении отсрочки, рассрочки, об уменьшении размера государственной пошлины;\n\n3) документы, подтверждающие обстоятельства, на которых истец основывает свои требования;\n\n4) (Пункт утратил силу - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n5) доверенность или иные документы, подтверждающие полномочия на подписание искового заявления, а также копии документов о высшем юридическом образовании или об ученой степени по юридической специальности представителя, подписавшего исковое заявление, либо документов, удостоверяющих его статус адвоката, патентного поверенного, арбитражного управляющего, единоличного органа управления организации; (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n6) копии определения арбитражного суда об обеспечении имущественных интересов до предъявления иска;\n\n7) документы, подтверждающие соблюдение истцом претензионного или иного досудебного порядка, за исключением случаев, если его соблюдение не предусмотрено федеральным законом; (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n71) документы, подтверждающие совершение стороной (сторонами) действий, направленных на примирение, если такие действия предпринимались и соответствующие документы имеются; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n8) проект договора, если заявлено требование о понуждении заключить договор;\n\n9) выписка из единого государственного реестра юридических лиц или единого государственного реестра индивидуальных предпринимателей с указанием сведений о месте нахождения или месте жительства истца и ответчика и (или) приобретении физическим лицом статуса индивидуального предпринимателя либо прекращении физическим лицом деятельности в качестве индивидуального предпринимателя или иной документ, подтверждающий указанные сведения или отсутствие таковых. Такие документы должны быть получены не ранее чем за тридцать дней до дня обращения истца в арбитражный суд. (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 126. Документы, прилагаемые к исковому заявлению","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0c76b24c34a14168b4cc2b73bb2cd051b66829820de8a1c70408609582af3b5"},{"code_id":"APK_RF","article_number":"127","version_date":"2002-07-24","article_text":"1. Вопрос о принятии искового заявления к производству арбитражного суда решается судьей единолично в пятидневный срок со дня поступления искового заявления в арбитражный суд.\n\n2. Арбитражный суд обязан принять к производству исковое заявление, поданное с соблюдением требований, предъявляемых настоящим Кодексом к его форме и содержанию.\n\n3. О принятии искового заявления арбитражный суд выносит определение, которым возбуждается производство по делу.","article_title":"Статья 127. Принятие искового заявления и возбуждение производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"592a07a1646ad3be3c3c7ae6f73d60a942cbcf86ccc551b009c574c7fda4f4f7"},{"code_id":"APK_RF","article_number":"127.1","version_date":"2002-07-24","article_text":"1. Судья отказывает в принятии искового заявления, заявления, если:\n\n1) исковое заявление, заявление подлежат рассмотрению в порядке конституционного или уголовного судопроизводства либо не подлежат рассмотрению в судах; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) имеются вступивший в законную силу принятый по спору между теми же лицами, о том же предмете и по тем же основаниям судебный акт арбитражного суда, суда общей юрисдикции или компетентного суда иностранного государства, за исключением случаев, если арбитражный суд отказал в признании и приведении в исполнение решения иностранного суда, а также определение о прекращении производства по делу в связи с принятием отказа истца от иска или утверждением мирового соглашения сторон либо определение об отказе в принятии искового заявления, заявления;\n\n3) имеется ставшее обязательным для сторон и принятое по спору между теми же сторонами, о том же предмете и по тем же основаниям решение третейского суда, за исключением случаев, если арбитражный суд отказал в выдаче исполнительного листа на принудительное исполнение решения третейского суда либо если арбитражный суд отменил указанное решение.\n\n2. Судья Суда по интеллектуальным правам отказывает в принятии заявления об оспаривании нормативного правового акта либо акта, содержащего разъяснения законодательства и обладающего нормативными свойствами, в случае, если имеется вступившее в законную силу решение арбитражного суда или суда общей юрисдикции по ранее рассмотренному делу, проверившего по тем же основаниям соответствие оспариваемого нормативного правового акта иному нормативному правовому акту, имеющему большую юридическую силу, либо проверившего по тем же основаниям оспариваемый акт, содержащий разъяснения законодательства и обладающий нормативными свойствами.\n\n3. Об отказе в принятии искового заявления, заявления судья выносит определение, в котором указывает обстоятельства, послужившие основанием для отказа в принятии искового заявления, заявления, и решает вопрос о возврате государственной пошлины лицу, предъявившему исковое заявление, заявление, если государственная пошлина была уплачена. Копия определения вместе с исковым заявлением, заявлением и прилагаемыми к нему документами направляется указанному лицу не позднее пяти дней со дня поступления искового заявления, заявления в суд.\n\n4. Отказ в принятии искового заявления, заявления препятствует повторному обращению в суд с такими заявлениями к тому же ответчику, о том же предмете и по тем же основаниям.\n\n5. Определение арбитражного суда об отказе в принятии искового заявления, заявления может быть обжаловано.\n\nВ случае отмены определения об отказе в принятии искового заявления, заявления такие заявления считаются поданными в день первоначального обращения в арбитражный суд.\n\n(Дополнение статьей - Федеральный закон от 19.12.2016 № 435-ФЗ)","article_title":"Статья 127.1. Отказ в принятии искового заявления, заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a51bb11b7bb6bfa393f3443ebf61c1dfc83004be94713ffb678ecfd7ad791a2"},{"code_id":"APK_RF","article_number":"128","version_date":"2002-07-24","article_text":"1. Арбитражный суд, установив при рассмотрении вопроса о принятии искового заявления к производству, что оно подано с нарушением требований, установленных статьями 125 и 126 настоящего Кодекса, выносит определение об оставлении заявления без движения.\n\n2. В определении арбитражный суд указывает основания для оставления искового заявления без движения и срок, в течение которого истец должен устранить обстоятельства, послужившие основанием для\n\nоставления искового заявления без движения.\n\nКопия определения об оставлении искового заявления без движения направляется истцу не позднее следующего дня после дня его вынесения.\n\n3. В случае, если обстоятельства, послужившие основанием для оставления искового заявления без движения, будут устранены в срок, установленный в определении арбитражного суда, заявление считается поданным в день его первоначального поступления в суд и принимается к производству арбитражного суда.\n\n4. В случае, если указанные в части 2 настоящей статьи обстоятельства не будут устранены в срок, установленный в определении, арбитражный суд возвращает исковое заявление и прилагаемые к нему документы в порядке, предусмотренном статьей 129 настоящего Кодекса.","article_title":"Статья 128. Оставление искового заявления без движения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1bb085de35495a00e3c921dd63eb186fef0cec2f8a22095d494a0f7489927e49"},{"code_id":"APK_RF","article_number":"129","version_date":"2002-07-24","article_text":"1. Арбитражный суд возвращает исковое заявление, если при рассмотрении вопроса о принятии заявления установит, что:\n\n1) дело неподсудно данному арбитражному суду или подсудно суду общей юрисдикции; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) (Пункт утратил силу - Федеральный закон от 19.07.2009 № 205-ФЗ)\n\n21) заявленные требования подлежат рассмотрению в порядке приказного производства; (Дополнение пунктом - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n3) до вынесения определения о принятии искового заявления к производству арбитражного суда от истца поступило ходатайство о возвращении заявления;\n\n4) не устранены обстоятельства, послужившие основаниями для оставления искового заявления без движения, в срок, установленный в определении суда;\n\n5) истцом не соблюден претензионный или иной досудебный порядок урегулирования спора с ответчиком, если такой порядок является обязательным в силу закона; (Дополнение пунктом - Федеральный закон от 02.03.2016 № 47-ФЗ)\n\n6) исковое заявление не подписано или исковое заявление подписано  лицом, не имеющим полномочий на его подписание. (Дополнение пунктом - Федеральный закон от 28.11.2018 № 451-ФЗ) (В редакции Федерального закона от 02.12.2019 № 406-ФЗ)\n\nАрбитражный суд также возвращает исковое заявление, если отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины, об уменьшении ее размера.\n\n2. О возвращении искового заявления арбитражный суд выносит определение.\n\nВ определении указываются основания для возвращения заявления, решается вопрос о возврате государственной пошлины из федерального бюджета.\n\n3. Копия определения о возвращении искового заявления направляется истцу не позднее следующего дня после дня вынесения определения или после истечения срока, установленного судом для устранения обстоятельств, послуживших основанием для оставления заявления без движения, вместе с заявлением и прилагаемыми к нему документами.\n\n4. Определение арбитражного суда о возвращении искового заявления может быть обжаловано.\n\n5. В случае отмены определения исковое заявление считается поданным в день первоначального обращения в арбитражный суд.\n\n6. Возвращение искового заявления не препятствует повторному обращению с таким же требованием в арбитражный суд в общем порядке после устранения обстоятельств, послуживших основанием для его возвращения.","article_title":"Статья 129. Возвращение искового заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61b583bab63927a6fcfc88e92869864d4ce27fc3e68e5fbddb46863302bc0510"},{"code_id":"APK_RF","article_number":"13","version_date":"2002-07-24","article_text":"1. Арбитражные суды рассматривают дела на основании Конституции Российской Федерации, международных договоров Российской Федерации, федеральных конституционных законов, федеральных законов, нормативных правовых актов Президента Российской Федерации и нормативных правовых актов Правительства Российской Федерации, нормативных правовых актов федеральных органов исполнительной власти, конституций (уставов), законов и иных нормативных правовых актов субъектов Российской Федерации, актов органов местного самоуправления.\n\nАрбитражные суды в случаях, предусмотренных федеральным законом, применяют обычаи делового оборота.\n\n2. Арбитражный суд, установив при рассмотрении дела несоответствие нормативного правового акта иному имеющему большую юридическую силу нормативному правовому акту, в том числе издание его с превышением полномочий, принимает судебный акт в соответствии с нормативным правовым актом, имеющим большую юридическую силу.\n\n3. Если при рассмотрении конкретного дела арбитражный суд придет к выводу о несоответствии закона, примененного или подлежащего применению в рассматриваемом деле, Конституции Российской Федерации, арбитражный суд обращается в Конституционный Суд Российской Федерации с запросом о проверке конституционности этого закона.","article_title":"Статья 13. Нормативные правовые акты, применяемые при рассмотрении дел","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e1d65e6d88d045156e65ce9a44f9c000cd866afc7117fb1def5632eaffc08e9"},{"code_id":"APK_RF","article_number":"130","version_date":"2002-07-24","article_text":"1. Истец вправе соединить в одном заявлении несколько требований, связанных между собой по основаниям возникновения или представленным доказательствам.\n\n2. Арбитражный суд первой инстанции вправе объединить несколько однородных дел, в которых участвуют одни и те же лица, в одно производство для совместного рассмотрения.","article_title":"Статья 130. Соединение и разъединение нескольких требований","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a48c3df1d1096c20c1e9e91b67f1923e80dc77e6ceff5f365f5cf7526a52b170"},{"code_id":"APK_RF","article_number":"131","version_date":"2002-07-24","article_text":"1. Ответчик обязан направить или представить в арбитражный суд и лицам, участвующим в деле, отзыв на исковое заявление с указанием возражений относительно предъявленных к нему требований по каждому доводу, содержащемуся в исковом заявлении.\n\nТакой отзыв и прилагаемые к нему документы могут быть представлены в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В случаях и в порядке, которые установлены настоящим Кодексом, иные участники арбитражного процесса вправе направить в арбитражный суд и другим лицам, участвующим в деле, отзыв в письменной форме на исковое заявление.\n\nОтветчик направляет отзыв на исковое заявление на бумажном носителе в арбитражный суд и лицам, участвующим в деле, заказным письмом с уведомлением о вручении. Отзыв на исковое заявление в электронном виде направляется лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n1) наименование истца, его адрес или, если истцом является гражданин, его место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) наименование ответчика, его адрес или, если ответчиком является гражданин, его место жительства, дата и место рождения, место работы или дата и место государственной регистрации в качестве индивидуального предпринимателя; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) возражения относительно каждого довода, касающегося существа заявленных требований, со ссылкой на законы и иные нормативные правовые акты, а также на доказательства, обосновывающие возражения;\n\n31) сведения о предпринятых ответчиком действиях, направленных на примирение, если такие действия предпринимались; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n32) мнение ответчика о возможности примирения сторон; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n4) перечень прилагаемых к отзыву документов, в том числе подтверждающих совершение ответчиком действий, направленных на примирение, если такие действия предпринимались и соответствующие документы имеются. (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 131. Отзыв на исковое заявление","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc6602f6b17eec5626b71757116987274c5af2184fc7500e17eedb1131c0b22d"},{"code_id":"APK_RF","article_number":"132","version_date":"2002-07-24","article_text":"1. Ответчик до принятия арбитражным судом первой инстанции судебного акта, которым заканчивается рассмотрение дела по существу, вправе предъявить истцу встречный иск для рассмотрения его совместно с первоначальным иском.\n\n2. Предъявление встречного иска осуществляется по общим правилам предъявления исков.\n\n3. Встречный иск принимается арбитражным судом в случае, если:\n\n1) встречное требование направлено к зачету первоначального требования;\n\n2) удовлетворение встречного иска исключает полностью или в части удовлетворение первоначального иска;\n\n3) между встречным и первоначальным исками имеется взаимная связь и их совместное рассмотрение приведет к более быстрому и правильному рассмотрению дела.\n\n4. Арбитражный суд возвращает встречный иск, если отсутствуют условия, предусмотренные частью 3 настоящей статьи, по правилам статьи 129 настоящего Кодекса.","article_title":"Статья 132. Предъявление встречного иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b56e2820a171cce36fd1e11f428655cfe9b41ef1adde7237d4316c029772809a"},{"code_id":"APK_RF","article_number":"133","version_date":"2002-07-24","article_text":"1. Задачами подготовки дела к судебному разбирательству являются определение характера спорного правоотношения и подлежащего применению законодательства, обстоятельств, имеющих значение для правильного рассмотрения дела; разрешение вопроса о составе лиц, участвующих в деле, и других участников арбитражного процесса; оказание содействия лицам, участвующим в деле, в представлении необходимых доказательств; примирение сторон.\n\n2. Подготовка дела к судебному разбирательству проводится судьей единолично по каждому находящемуся в производстве арбитражного суда первой инстанции делу в целях обеспечения его правильного и своевременного рассмотрения.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 133. Задачи подготовки дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bd525880ef4c1904113e9f25750144c1d7a28abf44943a58e84d1f3667913c0"},{"code_id":"APK_RF","article_number":"134","version_date":"2002-07-24","article_text":"1. Арбитражный суд первой инстанции после принятия заявления к производству выносит определение о подготовке дела к судебному разбирательству и указывает сторонам на возможность заявить ходатайство о рассмотрении дела с участием арбитражных заседателей, обратиться за содействием к суду или посреднику, в том числе медиатору, судебному примирителю, в целях урегулирования спора или использовать другие примирительные процедуры, а также на действия, которые надлежит совершить лицам, участвующим в деле, и сроки совершения этих действий.\n\nВ целях урегулирования спора судья принимает меры для примирения сторон, в том числе может предложить сторонам использовать какую-либо примирительную процедуру, отложить проведение предварительного судебного заседания, совершение других подготовительных действий.\n\nНа подготовку дела к судебному разбирательству может быть указано в определении о принятии заявления к производству.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n2. Подготовка дела к судебному разбирательству проводится в срок, определяемый судьей с учетом обстоятельств конкретного дела и необходимости совершения соответствующих процессуальных действий, и завершается проведением предварительного судебного заседания, если в соответствии с настоящим Кодексом не установлено иное.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 134. Срок подготовки дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a65fbfdeb1daa31926001690ec33ea96a5d96efbe83a5ecc5d54a74634bc3aa"},{"code_id":"APK_RF","article_number":"135","version_date":"2002-07-24","article_text":"1. При подготовке дела к судебному разбирательству судья:\n\n1) вызывает стороны и (или) их представителей и проводит с ними собеседование в целях выяснения обстоятельств, касающихся существа заявленных требований и возражений; предлагает раскрыть доказательства, их подтверждающие, и представить при необходимости дополнительные доказательства в определенный срок; разъясняет сторонам их права и обязанности, последствия совершения или несовершения процессуальных действий в установленный срок; определяет по согласованию со сторонами сроки представления необходимых доказательств и проведения предварительного судебного заседания;\n\n2) разъясняет сторонам их право на рассмотрение дела с участием арбитражных заседателей, право передать спор на разрешение третейского суда, право обратиться на любой стадии арбитражного процесса в целях урегулирования спора за содействием к посреднику, в том числе медиатору, судебному примирителю, использовать другие примирительные процедуры, разъясняет условия и порядок реализации данного права, существо и преимущества примирительных процедур, а также последствия совершения таких действий, принимает меры для заключения сторонами мирового соглашения, содействует примирению сторон; (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n3) оказывает содействие сторонам в получении необходимых доказательств, истребует по ходатайству сторон, а в случаях, предусмотренных настоящим Кодексом, по своей инициативе необходимые доказательства, разрешает вопросы о назначении экспертизы, вызове в судебное заседание экспертов, свидетелей, привлечении переводчика, специалиста, необходимости осмотра на месте письменных и вещественных доказательств, а также принимает иные меры для представления сторонами доказательств; (В редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\n4) по ходатайству сторон разрешает вопросы об обеспечении иска, о предоставлении встречного обеспечения, а также об обеспечении доказательств, направляет судебные поручения;\n\n5) рассматривает вопросы о вступлении в дело других лиц, замене ненадлежащего ответчика, соединении и разъединении нескольких требований, принятии встречного иска, возможности проведения выездного судебного заседания;\n\n6) совершает иные направленные на обеспечение правильного и своевременного рассмотрения дела действия.\n\n2. Действия по подготовке дела к судебному разбирательству совершаются судьей в порядке, предусмотренном настоящим Кодексом.\n\n3. Суд выносит определение о переходе к рассмотрению дела в порядке упрощенного производства в случае, если при подготовке к судебному разбирательству дела истцом заявлено ходатайство о рассмотрении дела в порядке упрощенного производства и в арбитражный суд представлено согласие ответчика на рассмотрение дела в порядке упрощенного производства или суд по своей инициативе предлагает рассмотреть дело в порядке упрощенного производства и при согласии сторон выносит соответствующее определение.\n\nОдновременно с указанным определением сторонам направляются данные, необходимые для идентификации сторон, в целях доступа к материалам дела в электронном виде.\n\nИсковое заявление, заявление по данному делу размещаются в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" в режиме ограниченного доступа не позднее следующего дня после дня вынесения указанного определения. (В редакции федеральных законов от 23.06.2016 № 220-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n(Дополнение частью - Федеральный закон от 25.06.2012 № 86-ФЗ)","article_title":"Статья 135. Действия по подготовке дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"613cc6477db77fe4cabaff1a6785f6d037f869ccebd36a0c6c6be51ded199f20"},{"code_id":"APK_RF","article_number":"136","version_date":"2002-07-24","article_text":"При неявке в предварительное судебное заседание надлежащим образом извещенных истца и (или) ответчика, других заинтересованных лиц, которые могут быть привлечены к участию в деле, заседание проводится в их отсутствие.\n\n1) разрешает ходатайства сторон;\n\n2) определяет достаточность представленных доказательств, доводит до сведения сторон, какие доказательства имеются в деле;\n\n21) выясняет мнение сторон о возможности урегулировать спор, предлагает сторонам использовать примирительные процедуры; при выявлении намерения сторон обратиться к судебному примирителю суд утверждает его кандидатуру, выбранную сторонами, в порядке, установленном настоящим Кодексом; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n3) выносит на рассмотрение вопросы, разрешаемые при подготовке дела к судебному разбирательству, и совершает предусмотренные настоящим Кодексом иные процессуальные действия.\n\nтву лиц, участвующих в деле, вправе объявить перерыв в предварительном судебном заседании на срок не более пяти дней для представления ими дополнительных доказательств.","article_title":"Статья 136. Предварительное судебное заседание","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86c67f0cdfa63c53fd89949527cd9ff21087b9c1441d09575986903e5937a5b9"},{"code_id":"APK_RF","article_number":"137","version_date":"2002-07-24","article_text":"1. Судья, признав дело подготовленным, выносит определение о назначении дела к судебному разбирательству.\n\n2. В определении о назначении дела к судебному разбирательству указывается на окончание подготовки дела к судебному разбирательству и разрешение вопросов о привлечении к делу третьих лиц, принятие встречного иска, соединение или разъединение нескольких требований, привлечение арбитражных заседателей, а также на разрешение других вопросов, если по ним не были вынесены соответствующие определения, время и место проведения судебного заседания в арбитражном суде первой инстанции.\n\n3. Копии определения о назначении дела к судебному разбирательству направляются лицам, участвующим в деле.","article_title":"Статья 137. Назначение дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4868312f81d6ca81ba370f34bf352e721e105558da57a798eba4f72144d0a4d8"},{"code_id":"APK_RF","article_number":"138","version_date":"2002-07-24","article_text":"1. Арбитражный суд принимает меры для примирения сторон, содействует им в урегулировании спора, руководствуясь при этом интересами сторон и задачами судопроизводства в арбитражных судах.\n\n2. Примирение сторон осуществляется на основе принципов добровольности, сотрудничества, равноправия и конфиденциальности.\n\n3. Стороны пользуются равными правами на выбор примирительной процедуры, определение условий ее проведения, а также кандидатуры посредника, в том числе медиатора, судебного примирителя. По указанным вопросам сторонами может быть заключено соглашение.\n\n4. Примирение сторон возможно на любой стадии арбитражного процесса и при исполнении судебного акта, если иное не предусмотрено настоящим Кодексом и иным федеральным законом.\n\n(Статья в редакции Федерального закона от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138. Примирение сторон","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9fea06e5c40001d6908762c3727897fd744ce509c3ec83bf0dd17fa645779722"},{"code_id":"APK_RF","article_number":"138.1","version_date":"2002-07-24","article_text":"1. Примирительная процедура может быть проведена по ходатайству сторон (стороны) либо по предложению арбитражного суда.\n\nПредложение арбитражного суда провести примирительную процедуру может содержаться в определении о принятии искового заявления (заявления) к производству, о подготовке дела к судебному разбирательству или в ином определении по делу, а также может быть сделано судом в устной форме.\n\nДля рассмотрения сторонами вопроса о возможности использовать примирительную процедуру арбитражный суд может объявить перерыв в судебном заседании.\n\n2. В случае согласия сторон с предложением арбитражного суда о проведении примирительной процедуры, удовлетворения ходатайства о проведении примирительной процедуры сторон или одной стороны при согласии другой стороны, а также в случае, предусмотренном частью 2 статьи 190 настоящего Кодекса, арбитражный суд выносит определение о проведении примирительной процедуры и при необходимости об отложении судебного разбирательства.\n\nВ определении о проведении примирительной процедуры арбитражный суд указывает наименования сторон, предмет спора и круг вопросов, для урегулирования которых может быть использована примирительная процедура, сроки проведения примирительной процедуры.\n\nВ определении о проведении примирительной процедуры могут содержаться и иные указания, необходимые для обеспечения надлежащего проведения примирительной процедуры.\n\n3. Примирительная процедура должна быть завершена в срок, установленный судом в определении о проведении примирительной процедуры. По ходатайству сторон указанный срок может быть продлен арбитражным судом.\n\n4. В ходе использования примирительной процедуры стороны могут достичь результатов примирения, установленных настоящим Кодексом.\n\n5. В случае, если стороны не достигли примирения, отказались от проведения примирительных процедур либо истек срок их проведения, арбитражный суд возобновляет судебное разбирательство в порядке, установленном частью 10 статьи 158 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.1. Порядок и сроки проведения примирительной процедуры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bc93519f423b0c4bfcee5db223225fb69840c8ce1d0f22fca3502e514857a150"},{"code_id":"APK_RF","article_number":"138.2","version_date":"2002-07-24","article_text":"Споры могут быть урегулированы путем проведения переговоров, посредничества, в том числе медиации, судебного примирения, или использования других примирительных процедур, если это не противоречит федеральному закону.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.2. Виды примирительных процедур","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2201b23ada1bc7be5e2490803dc8f362588f51dd106d0e4c37b126e948e1411"},{"code_id":"APK_RF","article_number":"138.3","version_date":"2002-07-24","article_text":"1. Стороны вправе урегулировать спор путем проведения переговоров в целях примирения.\n\n2. Переговоры осуществляются на условиях, определяемых сторонами.\n\n3. В случаях, предусмотренных федеральным законом или договором, переговоры проводятся в обязательном порядке.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.3. Переговоры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff16d0e662b6a9f4dab114530ddaf94c1f6c6974d16d83af660378b543c35a77"},{"code_id":"APK_RF","article_number":"138.4","version_date":"2002-07-24","article_text":"1. Стороны вправе урегулировать спор путем применения процедуры медиации в порядке, установленном настоящим Кодексом и федеральным законом.\n\n2. В случае заявления сторонами соответствующего ходатайства арбитражный суд откладывает судебное разбирательство на основании части 2 статьи 158 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.4. Медиация","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"82f979e6de7cf96e19ba1e8a96f75e08a8c320b5057b7f1fcd32e695b2437ffa"},{"code_id":"APK_RF","article_number":"138.5","version_date":"2002-07-24","article_text":"1. Стороны вправе урегулировать спор путем использования примирительной процедуры с участием судебного примирителя (судебное примирение).\n\n2. Судебное примирение осуществляется на основе принципов независимости, беспристрастности и добросовестности судебного примирителя.\n\nПорядок проведения судебного примирения и требования к судебному примирителю определяются настоящим Кодексом и Регламентом проведения судебного примирения, утверждаемым Верховным Судом Российской Федерации.\n\n3. Судебным примирителем является судья в отставке. Список судебных примирителей формируется и утверждается Пленумом Верховного Суда Российской Федерации на основе предложений арбитражных судов о кандидатурах судебных примирителей из числа судей в отставке, изъявивших желание выступать в качестве судебного примирителя.\n\nСудебный примиритель участвует в процедуре судебного примирения с учетом положений настоящего Кодекса и законодательства о статусе судей в Российской Федерации.\n\n4. Кандидатура судебного примирителя определяется по взаимному согласию сторон из списка судебных примирителей и утверждается определением суда.\n\n5. В целях соотнесения и сближения позиций сторон по делу и выявления дополнительных возможностей для урегулирования спора с учетом интересов сторон, оказания им содействия в достижении взаимоприемлемого результата примирения, основанного также на понимании и оценке сторонами обоснованности заявленных требований и возражений, судебный примиритель вправе вести переговоры со сторонами, другими лицами, участвующими в деле, изучать представленные сторонами документы, знакомиться с материалами дела с согласия арбитражного суда и осуществлять другие действия, необходимые для эффективного урегулирования спора и предусмотренные Регламентом проведения судебного примирения, в том числе давать сторонам рекомендации в целях скорейшего урегулирования спора и сохранения между сторонами деловых отношений.\n\nСудебный примиритель не является участником судебного разбирательства и не вправе совершать действия, влекущие за собой возникновение, изменение либо прекращение прав или обязанностей лиц, участвующих в деле, и других участников арбитражного процесса.\n\nСудья вправе запросить информацию о ходе примирительной процедуры не чаще чем один раз в четырнадцать календарных дней.\n\n6. Порядок и условия оплаты труда судей, пребывающих в отставке и осуществляющих функции судебных примирителей, определяются Правительством Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.5. Судебное примирение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1469b3e0e6089e4781155e7d7b385f36b28ab0525c8683976547c20026c90099"},{"code_id":"APK_RF","article_number":"138.6","version_date":"2002-07-24","article_text":"1. Результатами примирения лиц, участвующих в деле, могут быть, в частности:\n\n1) мировое соглашение в отношении всех или части заявленных требований;\n\n2) частичный или полный отказ от иска;\n\n3) частичное или полное признание иска;\n\n4) полный или частичный отказ от апелляционной, кассационной жалобы, надзорной жалобы (представления);\n\n5) признание обстоятельств, на которых другая сторона основывает свои требования или возражения;\n\n6) соглашение по обстоятельствам дела;\n\n7) подписание письма-согласия на государственную регистрацию товарного знака.\n\n2. Признание обстоятельств, признание иска (требований), отказ от иска (требований) полностью или в части принимаются арбитражным судом в порядке, установленном настоящим Кодексом.\n\n3. Признание обстоятельств, на которых другая сторона основывает свои требования или возражения, может быть осуществлено в форме одностороннего заявления о согласии с позицией другой стороны или в форме соглашения по обстоятельствам дела.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.6. Результаты примирительных процедур","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e83456382b23fb39526728e806741446245ba489096c5fec5a241ca39761c6d0"},{"code_id":"APK_RF","article_number":"14","version_date":"2002-07-24","article_text":"1. При применении норм иностранного права арбитражный суд устанавливает содержание этих норм в соответствии с их официальным толкованием, практикой применения и доктриной в соответствующем иностранном государстве.\n\n2. В целях установления содержания норм иностранного права суд может обратиться в установленном порядке за содействием и разъяснением в Министерство юстиции Российской Федерации и иные компетентные органы или организации Российской Федерации и за границей либо привлечь экспертов.\n\nЛица, участвующие в деле, могут представлять документы, подтверждающие содержание норм иностранного права, на которые они ссылаются в обоснование своих требований или возражений, и иным образом содействовать суду в установлении содержания этих норм.\n\nПо требованиям, связанным с осуществлением сторонами предпринимательской и иной экономической деятельности, обязанность доказывания содержания норм иностранного права может быть возложена судом на стороны.\n\n3. Если содержание норм иностранного права, несмотря на принятые в соответствии с настоящей статьей меры, в разумные сроки не установлено, арбитражный суд применяет соответствующие нормы российского права.","article_title":"Статья 14. Применение норм иностранного права","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2ab390e3c296616410f88591dd711f00f3ea6fc5051f9f1c2dab68b12fed3641"},{"code_id":"APK_RF","article_number":"140","version_date":"2002-07-24","article_text":"1. Мировое соглашение заключается в письменной форме и подписывается сторонами или их представителями при наличии у них полномочий на заключение мирового соглашения, специально предусмотренных в доверенности или ином документе, подтверждающих полномочия представителя.\n\n2. Мировое соглашение должно содержать согласованные сторонами сведения об условиях, о размере и о сроках исполнения обязательств друг перед другом или одной стороной перед другой.\n\nВ мировом соглашении могут содержаться условия об отсрочке или о рассрочке исполнения обязательств ответчиком, об уступке прав требования, о полном или частичном прощении либо признании долга, о распределении судебных расходов, санкции за его неисполнение или ненадлежащее исполнение и иные условия, не противоречащие федеральному закону. (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n3. Если в мировом соглашении отсутствует условие о распределении судебных расходов, арбитражный суд разрешает этот вопрос при утверждении мирового соглашения в общем порядке, установленном настоящим Кодексом.\n\n4. Мировое соглашение составляется и подписывается в количестве экземпляров, превышающем на один экземпляр количество лиц, заключивших мировое соглашение; один из этих экземпляров приобщается арбитражным судом, утвердившим мировое соглашение, к материалам дела.","article_title":"Статья 140. Форма и содержание мирового соглашения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e26a6a3a48f114f89ceaf15275b410814d9656bf930ebb6218dc05e51d35aef9"},{"code_id":"APK_RF","article_number":"141","version_date":"2002-07-24","article_text":"1. Мировое соглашение утверждается арбитражным судом, в производстве которого находится дело. В случае, если мировое соглашение заключено в процессе исполнения судебного акта, оно представляется на утверждение арбитражного суда первой инстанции по месту исполнения судебного акта или в арбитражный суд, принявший указанный судебный акт.\n\n2. Вопрос об утверждении мирового соглашения рассматривается арбитражным судом в судебном заседании. Лица, участвующие в деле, извещаются о времени и месте судебного заседания.\n\n3. В случае неявки в судебное заседание лиц, заключивших мировое соглашение и извещенных надлежащим образом о времени и месте судебного заседания, вопрос об утверждении мирового соглашения не рассматривается арбитражным судом, если от этих лиц не поступило заявление о рассмотрении данного вопроса в их отсутствие.\n\nПри рассмотрении вопроса об утверждении мирового соглашения в случае обжалования судебного акта или его исполнения законность и обоснованность соответствующего судебного акта не проверяются.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\nПри рассмотрении вопроса об утверждении мирового соглашения арбитражный суд вправе предложить сторонам исключить из мирового соглашения отдельные условия, противоречащие закону или нарушающие права и законные интересы других лиц.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n1) утверждение мирового соглашения или отказ в утверждении мирового соглашения;\n\n2) условия мирового соглашения;\n\n3) возвращение истцу из федерального бюджета части уплаченной им государственной пошлины в размерах, установленных федеральными законами о налогах и сборах;\n\n4) распределение судебных расходов.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\nУтверждение мирового соглашения в судах апелляционной, кассационной и надзорной инстанций по предмету заявленных требований влечет за собой отмену судебного акта и прекращение производства по делу.\n\nУтверждение мирового соглашения, заключенного в процессе исполнения судебного акта, влечет за собой прекращение исполнения этого судебного акта при оставлении его в силе. На это указывается в определении суда.\n\nУтверждение мирового соглашения, заключенного при рассмотрении заявления о распределении судебных расходов, понесенных в судах первой, апелляционной, кассационной и надзорной инстанций, влечет за собой прекращение производства по заявлению о распределении судебных расходов.\n\n(Дополнение частью - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 141. Утверждение арбитражным судом мирового соглашения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43390ec411e8b7309dc544af9b20dfa748fc52e90f5ac821af11ab8a4482a639"},{"code_id":"APK_RF","article_number":"142","version_date":"2002-07-24","article_text":"1. Мировое соглашение исполняется лицами, его заключившими, добровольно в порядке и в сроки, которые предусмотрены этим соглашением.\n\n2. Мировое соглашение, не исполненное добровольно, подлежит принудительному исполнению по правилам раздела VII настоящего Кодекса на основании исполнительного листа, выдаваемого арбитражным судом по ходатайству лица, заключившего мировое соглашение.","article_title":"Статья 142. Исполнение мирового соглашения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43c1c144f8981ef5de080f41069bb91f5cfb2e701d16c27515fafea82c5c78fa"},{"code_id":"APK_RF","article_number":"143","version_date":"2002-07-24","article_text":"1. Арбитражный суд обязан приостановить производство по делу в случае:\n\n1) невозможности рассмотрения данного дела до разрешения другого дела, рассматриваемого Конституционным Судом Российской Федерации, Верховным Судом Российской Федерации, судом общей юрисдикции, арбитражным судом; (В редакции  федеральных законов от 14.07.2022 № 337-ФЗ, от 25.12.2023 № 667-ФЗ)\n\n2) участия гражданина, являющегося стороной в деле, в боевых действиях в составе Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов, созданных в соответствии с законодательством Российской Федерации, в проведении контртеррористической операции, призыва его на военную службу по мобилизации, заключения им контракта о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации, выполнения им задач в условиях чрезвычайного или военного положения, вооруженного конфликта, если такой гражданин не заявил ходатайство о рассмотрении дела в его отсутствие; (В редакции  федеральных законов от 29.12.2022 № 603-ФЗ, от 25.12.2023 № 639-ФЗ)\n\n3) смерти гражданина, являющегося стороной в деле или третьим лицом, заявляющим самостоятельные требования относительно предмета спора, если спорное правоотношение допускает правопреемство; (В редакции Федерального закона от 22.04.2013 № 61-ФЗ)\n\n4) утраты гражданином, являющимся стороной в деле, дееспособности.\n\n2. Арбитражный суд приостанавливает производство по делу и в иных предусмотренных федеральным законом случаях.","article_title":"Статья 143. Обязанность арбитражного суда приостановить производство по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8637bd3ac1201fc580e2bdb9426fc2fd7b5b409bebc9338177f7e834d94e9380"},{"code_id":"APK_RF","article_number":"144","version_date":"2002-07-24","article_text":"Арбитражный суд вправе приостановить производство по делу в случае:\n\n1) назначения арбитражным судом экспертизы;\n\n2) реорганизации организации, являющейся лицом, участвующим в деле;\n\n3) привлечения гражданина, являющегося лицом, участвующим в деле, для выполнения государственной об\n\nязанности;\n\n4) нахождения гражданина, являющегося лицом, участвующим в деле, в лечебном учреждении или длительной служебной командировке;\n\n5) рассмотрения международным судом, судом иностранного государства другого дела, решение по которому может иметь значение для рассмотрения данного дела;\n\n6) участия гражданина, осуществляющего полномочия единоличного исполнительного органа организации, являющейся лицом, участвующим в деле, в боевых действиях в составе Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов, созданных в соответствии с законодательством Российской Федерации, в проведении контртеррористической операции, призыва его на военную службу по мобилизации, заключения им контракта о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации, выполнения им задач в условиях чрезвычайного или военного положения, вооруженного конфликта, если рассмотрение дела без участия такого гражданина невозможно и полномочия по управлению указанной организацией не переданы им в порядке, установленном законодательством Российской Федерации. (Дополнение пунктом - Федеральный закон от 29.12.2022 № 603-ФЗ) (В редакции  Федерального закона от 25.12.2023 № 639-ФЗ)","article_title":"Статья 144. Право арбитражного суда приостановить производство по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"029eea7f040aef0c579dc2c366436a6cf4e9083bb9d04db7761101c6904ed846"},{"code_id":"APK_RF","article_number":"145","version_date":"2002-07-24","article_text":"Производство по делу приостанавливается:\n\n1) в случаях, предусмотренных пунктом 1 части 1 статьи 143 и пунктом 5 статьи 144 настоящего Кодекса, до вступления в законную силу судебного акта соответствующего суда;\n\n2) в случаях, предусмотренных пунктом 2 части 1 статьи 143 и пунктами 4 и 6 статьи 144 настоящего Кодекса, до устранения обстоятельств, послуживших основанием для приостановления производства по делу; (В редакции  Федерального закона от 29.12.2022 № 603-ФЗ)\n\n3) в случаях, предусмотренных пунктами 3 и 4 части 1 статьи 143 и пунктом 2 статьи 144 настоящего Кодекса, до определения правопреемника лица, участвующего в деле, или назначения недееспособному лицу представителя;\n\n4) в случае, предусмотренном пунктом 1 статьи 144 настоящего Кодекса, до истечения срока, установленного арбитражным судом.","article_title":"Статья 145. Сроки приостановления производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2637cee6264ddd3e37b7272bae9d8148b1c45db7e7e801fb9f2ed10413063712"},{"code_id":"APK_RF","article_number":"146","version_date":"2002-07-24","article_text":"Арбитражный суд возобновляет производство по делу по заявлению лиц, участвующих в деле, или по своей инициативе после устранения обстоятельств, вызвавших его приостановление, либо до их устранения по заявлению лица, по ходатайству которого производство по делу было приостановлено.","article_title":"Статья 146. Возобновление производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ac6eeffc526fb3d58fb4062bbf6cd20d9d45666b2db78e1efca3d573c9416802"},{"code_id":"APK_RF","article_number":"147","version_date":"2002-07-24","article_text":"1. О приостановлении производства по делу, его возобновлении или об отказе в возобновлении арбитражный суд выносит определение.\n\nКопии определения направляются лицам, участвующим в деле.\n\n2. Определение арбитражного суда о приостановлении производства по делу, об отказе в возобновлении производства по делу может быть обжаловано.","article_title":"Статья 147. Порядок приостановления и возобновления производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ae203152800c60ecd2dc2181a19ae2a503b019a8ed6df9a2c7e41787c7105ba"},{"code_id":"APK_RF","article_number":"148","version_date":"2002-07-24","article_text":"1) в производстве арбитражного суда, суда общей юрисдикции, третейского суда имеется дело по спору между теми же лицами, о том же предмете и по тем же основаниям;\n\n2) истцом не соблюден претензионный или иной досудебный порядок урегулирования спора с ответчиком, за исключением случаев, если его соблюдение не предусмотрено федеральным законом; (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n3) при рассмотрении заявления об установлении фактов, имеющих юридическое значение, выясняется, что возник спор о праве;\n\n4) заявлено требование, которое в соответствии с федеральным законом должно быть рассмотрено в деле о банкротстве;\n\n5) имеется соглашение сторон о рассмотрении данного спора третейским судом, если любая из сторон не позднее дня представления своего первого заявления по существу спора в арбитражном суде первой инстанции заявит по этому основанию возражение в отношении рассмотрения дела в арбитражном суде, за исключением случаев, если арбитражный суд установит, что это соглашение недействительно, утратило силу или не может быть исполнено;\n\n6) стороны заключили соглашение о передаче спора на разрешение третейского суда во время судебного разбирательства до принятия судебного акта, которым заканчивается рассмотрение дела по существу, если любая из сторон заявит по этому основанию возражение в отношении рассмотрения дела в арбитражном суде, за исключением случаев, если арбитражный суд установит, что это соглашение недействительно, утратило силу или не может быть исполнено;\n\n7) исковое заявление не подписано или подписано лицом, не имеющим права подписывать его, либо лицом, должностное положение которого не указано;\n\n8) заявлено исковое требование о взыскании судебных расходов, которое подлежит рассмотрению в соответствии со статьей 112 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n9) истец повторно не явился в судебное заседание, в том числе по вызову суда, и не заявил ходатайство о рассмотрении дела в его отсутствие или об отложении судебного разбирательства, а ответчик не требует рассмотрения дела по существу. (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 148. Основания для оставления искового заявления без рассмотрения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a0a4c50495985fb4afd8aa1413be80db9bdb1a5045a5e93fbf7f5555ca9be4de"},{"code_id":"APK_RF","article_number":"149","version_date":"2002-07-24","article_text":"1. В случае оставления искового заявления без рассмотрения производство по делу заканчивается вынесением определения.\n\nВ определении арбитражный суд указывает основания для оставления искового заявления без рассмотрения, а также решает вопрос о возврате государственной пошлины из федерального бюджета в случае, предусмотренном частью 2 статьи 148 настоящего Кодекса. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nКопии определения направляются лицам, участвующим в деле.\n\n2. Определение арбитражного суда об оставлении искового заявления без рассмотрения может быть обжаловано.\n\n3. Оставление искового заявления без рассмотрения не лишает истца права вновь обратиться в арбитражный суд с заявлением в общем порядке после устранения обстоятельств, послуживших основанием для оставления заявления без рассмотрения.","article_title":"Статья 149. Порядок и последствия оставления искового заявления без рассмотрения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"646b16b49394410f8fc2c9b69e860430370303abaae95c15010b231e82fab2ea"},{"code_id":"APK_RF","article_number":"15","version_date":"2002-07-24","article_text":"1. Арбитражный суд принимает судебные акты в форме судебного приказа, решения, постановления, определения.\n\n2. Судебный акт, вынесенный арбитражным судом первой инстанции в порядке приказного производства, именуется судебным приказом.\n\nСудебный акт, принятый арбитражным судом первой инстанции при рассмотрении дела по существу, именуется решением.\n\n3. Судебные акты, принимаемые арбитражными судами апелляционной инстанции и судами кассационной инстанции, образованными в соответствии с Федеральным конституционным законом от 28 апреля 1995 года № 1-ФКЗ \"Об арбитражных судах в Российской Федерации\", по результатам рассмотрения апелляционных и кассационных жалоб, именуются постановлениями. Судебные акты, выносимые Верховным Судом Российской Федерации по результатам рассмотрения кассационных жалобы, представления в порядке, установленном статьями 2911 - 29115 настоящего Кодекса, именуются определениями. Судебные акты, принимаемые Президиумом Верховного Суда Российской Федерации по результатам рассмотрения надзорных жалобы, представления в порядке, установленном статьями 3081 - 30813 настоящего Кодекса, именуются постановлениями.\n\nВсе иные судебные акты арбитражных судов, принимаемые в ходе осуществления судопроизводства, именуются определениями.\n\n4. Принимаемые арбитражным судом судебные приказы, решения, постановления, определения должны быть законными, обоснованными и мотивированными.\n\n5. Судебный акт, за исключением акта, содержащего сведения, составляющие государственную или иную охраняемую законом тайну, если дело рассмотрено в закрытом судебном заседании, может быть выполнен в форме электронного документа, который подписывается судьей усиленной квалифицированной электронной подписью. В случае, если судебный акт принят судом коллегиально, он подписывается всеми судьями, рассматривавшими дело, усиленной квалифицированной электронной подписью.\n\nПри выполнении судебного акта в форме электронного документа дополнительно выполняется экземпляр данного судебного акта на бумажном носителе.\n\n(Дополнение частью - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n(Статья в редакции Федерального закона от 02.03.2016 № 47-ФЗ)","article_title":"Статья 15. Судебные акты арбитражного суда, Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1ba77100a4b229b23d738d5fcb63ae1ac98b29ee5fd5229645a1622a5f3b783c"},{"code_id":"APK_RF","article_number":"150","version_date":"2002-07-24","article_text":"1. Арбитражный суд прекращает производство по делу, если установит, что:\n\n1) имеются основания, предусмотренные пунктом 1 части 1 статьи 1271 настоящего Кодекса; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) имеется вступивший в законную силу принятый по спору между теми же лицами, о том же предмете и по тем же основаниям судебный акт арбитражного суда, суда общей юрисдикции или компетентного суда иностранного государства, за исключением случаев, если арбитражный суд отказал в признании и приведении в исполнение решения иностранного суда;\n\n3) имеется принятое по спору между теми же лицами, о том же предмете и по тем же основаниям решение третейского суда, за исключением случаев, если арбитражный суд отказал в выдаче исполнительного листа на принудительное исполнение решения третейского суда либо если арбитражный суд отменил указанное решение; (В редакции Федерального закона от 29.12.2015 № 409-ФЗ)\n\n4) истец отказался от иска и отказ принят арбитражным судом;\n\n5) организация, являющаяся стороной в деле, ликвидирована;\n\n6) после смерти гражданина, являющегося стороной в деле, спорное правоотношение не допускает правопреемства;\n\n7) имеются основания, предусмотренные частью 7 статьи 194 настоящего Кодекса.","article_title":"Статья 150. Основания для прекращения производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0f63471fb90c31a726410e40ef5a078bd0fc54f76dbf4ef9de4ecf665b30ccf"},{"code_id":"APK_RF","article_number":"151","version_date":"2002-07-24","article_text":"1. О прекращении производства по делу арбитражный суд выносит определение.\n\nВ определении арбитражный суд указывает основания для прекращения производства по делу, а также разрешает вопросы о возврате государственной пошлины из федерального бюджета в случае, предусмотренном частью 1 статьи 150 настоящего Кодекса, и распределении между сторонами судебных расходов. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nКопии определения направляются лицам, участвующим в деле.\n\n2. Определение арбитражного суда о прекращении производства по делу может быть обжаловано.","article_title":"Статья 151. Порядок и последствия прекращения производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"003bf58415329e24ddf14b81f4f958a7fce9ef29df6691c9d74f777f92f3c9e5"},{"code_id":"APK_RF","article_number":"152","version_date":"2002-07-24","article_text":"Дело по спору о сносе самовольной постройки или ее приведении в соответствие с предельными параметрами разрешенного строительства, реконструкции объектов капитального строительства, установленными правилами землепользования и застройки, документацией по планировке территории, или обязательными требованиями к параметрам объектов капитального строительства, установленными федеральными законами, об изъятии земельного участка из земель сельскохозяйственного назначения должно быть рассмотрено арбитражным судом первой инстанции в срок, не превышающий одного месяца со дня поступления заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 340-ФЗ) (В редакции  Федерального закона от 05.12.2022 № 507-ФЗ)\n\n(Статья в редакции Федерального закона от 30.04.2010 № 69-ФЗ)","article_title":"Статья 152. Срок рассмотрения дела и принятия решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5fef23a0285c3ae6b846ecfd669658b717798c102cf30c0f2e02fda94b27a32e"},{"code_id":"APK_RF","article_number":"153","version_date":"2002-07-24","article_text":"1. Разбирательство дела осуществляется в судебном заседании арбитражного суда с обязательным извещением лиц, участвующих в деле, о времени и месте заседания.\n\n2. Судья, а при коллегиальном рассмотрении дела председательствующий в судебном заседании:\n\n1) открывает судебное заседание и объявляет, какое дело подлежит рассмотрению;\n\n2) проверяет явку в судебное заседание лиц, участвующих в деле, их представителей и иных участников арбитражного процесса, устанавливает их личность и проверяет полномочия; устанавливает, извещены ли надлежащим образом лица, не явившиеся в судебное заседание, и какие имеются сведения о причинах их неявки;\n\n3) выясняет вопрос о возможности слушания дела;\n\n4) объявляет состав арбитражного суда, сообщает, кто ведет протокол судебного заседания, кто участвует в качестве эксперта, переводчика, и разъясняет лицам, участвующим в деле, их право заявлять отводы;\n\n5) разъясняет лицам, участвующим в деле, и иным участникам арбитражного процесса их процессуальные права и обязанности;\n\n6) удаляет из зала судебного заседания явившихся свидетелей до начала их допроса;\n\n7) предупреждает переводчика об уголовной ответственности за заведомо неправильный перевод, эксперта за дачу заведомо ложного заключения, свидетелей (непосредственно перед их допросом) за дачу заведомо ложных показаний и отказ от дачи показаний;\n\n8) определяет с учетом мнений лиц, участвующих в деле, последовательность проведения процессуальных действий и продолжительность выступлений; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n9) выясняет, поддерживает ли истец иск, признает ли иск ответчик, не хотят ли стороны закончить дело мировым соглашением или применить процедуру медиации, о чем делаются соответствующие записи в протоколе судебного заседания; (В редакции Федерального закона от 27.07.2010 № 194-ФЗ)\n\n10) руководит судебным заседанием, обеспечивает условия для всестороннего и полного исследования доказательств и обстоятельств дела, обеспечивает рассмотрение заявлений и ходатайств лиц, участвующих в деле;\n\n11) принимает меры по обеспечению в судебном заседании надлежащего порядка.","article_title":"Статья 153. Судебное заседание арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40a0e6597dd190a5c59bf854fb0ffe34ac4e6396de81c245f8392918d7cb0b2b"},{"code_id":"APK_RF","article_number":"153.1","version_date":"2002-07-24","article_text":"В случае, если лицу, участвующему в деле, иным участникам арбитражного процесса, находящимся в местах содержания под стражей или в местах отбывания лишения свободы, содействие в участии в судебном заседании путем использования систем видеоконференц-связи оказывает соответствующее учреждение, арбитражный суд, рассматривающий дело, выносит определение о проведении такого судебного заседания в соответствии со статьями 184 и 185 настоящего Кодекса. Копия определения арбитражного суда направляется в учреждение, которое обеспечивает проведение судебного заседания путем использования систем видеоконференц-связи в соответствии со статьей 1551 Гражданского процессуального кодекса Российской Федерации. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Дополнение частью - Федеральный закон от 01.05.2016 № 137-ФЗ)\n\n1) отсутствует техническая возможность для участия в судебном заседании с использованием систем видеоконференц-связи;\n\n2) разбирательство дела осуществляется в закрытом судебном заседании.\n\n(Дополнение статьей - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 153.1. Участие в судебном заседании путем использования систем видеоконференц-связи","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe891764684949b24afc64b80aaf236e671e5e7b538ae7ebee5d99d856503231"},{"code_id":"APK_RF","article_number":"153.2","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, и иные участники арбитражного процесса могут участвовать в судебном заседании путем использования системы веб-конференции при условии заявления ими соответствующего ходатайства и при наличии в арбитражном суде технической возможности осуществления веб-конференции.\n\nУстановление личности гражданина, его представителя или представителя юридического лица, участвующих в судебном заседании путем использования системы веб-конференции, осуществляется с использованием информационно-технологических средств, обеспечивающих идентификацию лица без его личного присутствия (единой системы идентификации и аутентификации, единой биометрической системы).\n\nАрбитражный суд в электронном виде заблаговременно направляет лицам, участвующим в деле, информацию, необходимую для участия в судебном заседании путем использования системы веб-конференции. При отказе в удовлетворении ходатайства об участии в судебном заседании путем использования системы веб-конференции арбитражный суд в электронном виде направляет лицам, участвующим в деле, информацию о таком отказе с указанием его оснований. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n2. Арбитражный суд, рассматривающий дело, отказывает в удовлетворении ходатайства об участии в судебном заседании путем использования системы веб-конференции в случае, если:\n\n1) отсутствует техническая возможность для участия в судебном заседании с использованием системы веб-конференции;\n\n2) разбирательство дела осуществляется в закрытом судебном заседании.\n\n3. Лица, участвующие в деле, и иные участники арбитражного процесса, участвующие в судебном заседании путем использования системы веб-конференции, вправе в ходе судебного заседания подавать в арбитражный суд заявления, ходатайства и прилагаемые к ним документы в электронном виде.\n\n4. Арбитражный суд, рассматривающий дело, берет подписку у свидетелей, экспертов, переводчиков, участвующих в судебном заседании путем использования системы веб-конференции, о разъяснении им прав и обязанностей и предупреждении об ответственности за их нарушение, которая представляется в арбитражный суд в форме электронного документа, подписанного усиленной квалифицированной электронной подписью.\n\n5. При использ\n\nовании системы веб-конференции составляется протокол и ведется видеозапись судебного заседания. Материальный носитель видеозаписи судебного заседания приобщается к протоколу судебного заседания.\n\n(Дополнение статьей - Федеральный закон от 30.12.2021 № 440-ФЗ)","article_title":"Статья 153.2. Участие в судебном заседании путем использования системы веб-конференции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"29b4b9f6c2f1150fae3aa3855ea45b9023f943958e7041c077f920a15dc0eb33"},{"code_id":"APK_RF","article_number":"154","version_date":"2002-07-24","article_text":"1. При входе судей в зал судебного заседания все присутствующие в зале встают. Решение арбитражного суда все находящиеся в зале судебного заседания лица выслушивают стоя.\n\n2. Лица, участвующие в деле, и иные участники арбитражного процесса обращаются к арбитражному суду со словами: \"Уважаемый суд!\" Свои объяснения и показания суду, вопросы другим лицам, участвующим в деле, ответы на вопросы они дают стоя. Отступление от этого правила может быть допущено только с разрешения суда.","article_title":"Статья 154. Порядок в судебном заседании","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f5d05ecda0d7ed05c7b1efd033fc31479f5d744855b80fef59edb08ba7ea992"},{"code_id":"APK_RF","article_number":"155","version_date":"2002-07-24","article_text":"1. В ходе каждого судебного заседания арбитражного суда первой инстанции, а также при совершении отдельных процессуальных действий вне судебного заседания ведется протоколирование с использованием средств аудиозаписи и составляется протокол в письменной форме (далее также - протокол).\n\n2. Протокол является дополнительным средством фиксирования следующих данных о ходе судебного заседания:\n\n1) год, месяц, число и место проведения судебного заседания;\n\n2) время начала и окончания судебного заседания;\n\n3) наименование арбитражного суда, рассматривающего дело, состав суда;\n\n4) наименование и номер дела;\n\n5) сведения о предупреждении об уголовной ответственности переводчика за заведомо неправильный перевод, свидетелей за дачу заведомо ложных показаний и отказ от дачи показаний, эксперта за дачу заведомо ложного заключения;\n\n6) устные заявления и ходатайства лиц, участвующих в деле, консультации специалистов; (В редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\n7) соглашения сторон по фактическим обстоятельствам дела и заявленным требованиям и возражениям;\n\n8) определения, вынесенные судом без удаления из зала судебного заседания;\n\n9) отметка об использовании средств аудиозаписи, систем видеоконференц-связи либо системы веб-конференции и (или) иных технических средств, о проведении кино- и фотосъемки, видеозаписи, трансляции судебного заседания по радио, телевидению и в информационно-телекоммуникационной сети \"Интернет\" в ходе судебного заседания. При проведении трансляции судебного заседания указывается также наименование средства массовой информации или сайта в информационно-телекоммуникационной сети \"Интернет\", посредством которых осуществлялась трансляция; (В редакции федеральных законов от 29.07.2017 № 223-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n10) дата составления протокола.\n\n3. В протоколе о совершении отдельного процессуального действия указываются также сведения, полученные в результате совершения этого процессуального действия.\n\n4. Секретарь судебного заседания или помощник судьи составляет протокол и обеспечивает использование средств аудиозаписи и (или) иных технических средств в ходе судебного заседания.\n\n5. Протокол может быть написан от руки или составлен с использованием технических средств. Протокол подписывается председательствующим в судебном заседании, секретарем судебного заседания или помощником судьи, который составлял протокол судебного заседания, не позднее следующего дня после дня окончания судебного заседания, а протокол о совершении отдельного процессуального действия - непосредственно после совершения отдельного процессуального действия.\n\n6. Протоколирование судебного заседания с использованием средств аудиозаписи ведется непрерывно в ходе судебного заседания. Материальный носитель аудиозаписи приобщается к протоколу.\n\nВ случае, если арбитражным судом проводится стенографическая запись, а также видеозапись судебного заседания, в протоколе, составленном в письменной форме, должны быть указаны сведения, предусмотренные пунктами 5, 6, 8 и 9 части 2 настоящей статьи. Материальный носитель видеозаписи приобщается к протоколу.\n\nЗамечания на протокол, представленные в арбитражный суд по истечении пятидневного срока, судом не рассматриваются и возвращаются лицу, представившему эти замечания. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 155. Протокол","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c6e6e9862985d127a332f48f8eb80dc806a51b5bb4fa39a4f9b5ff17a800345"},{"code_id":"APK_RF","article_number":"156","version_date":"2002-07-24","article_text":"1. Непредставление отзыва на исковое заявление или дополнительных доказательств, которые арбитражный суд предложил представить лицам, участвующим в деле, не является препятствием к рассмотрению дела по имеющимся в деле доказательствам.\n\n2. Стороны вправе известить арбитражный суд о возможности рассмотрения дела в их отсутствие.\n\n3. При неявке в судебное заседание арбитражного суда истца и (или) ответчика, надлежащим образом извещенных о времени и месте судебного разбирательства, суд вправе рассмотреть дело в их отсутствие.\n\n4. В случае, если в судебное заседание не явились лица, участвующие в деле, а их явка в соответствии с настоящим Кодексом была признана обязательной арбитражным судом, суд может наложить на указанных лиц судебный штраф в порядке и в размерах, которые предусмотрены в главе 11 настоящего Кодекса.\n\n5. При неявке в судебное заседание иных лиц, участвующих в деле и надлежащим образом извещенных о времени и месте судебного разбирательства, суд рассматривает дело в их отсутствие.","article_title":"Статья 156. Рассмотрение дела при непредставлении отзыва на исковое заявление, дополнительных доказательств, а также в отсутствие лиц, участвующих в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46df8776d28fcdbf56af022e3a4c6cb097a3c4efca2fe07b0ff93a14f784c35a"},{"code_id":"APK_RF","article_number":"157","version_date":"2002-07-24","article_text":"1. При неявке в судебное заседание экспертов, свидетелей, переводчиков, надлежащим образом извещенных о времени и месте судебного заседания, арбитражный суд выносит определение об отложении судебного разбирательства, если стороны не заявили ходатайство о рассмотрении дела в отсутствие указанных лиц.\n\n2. В случае, если вызванные в судебное заседание эксперт, свидетель, переводчик не явились в суд по причинам, признанным судом неуважительными, суд может наложить на них судебный штраф в порядке и в размере, которые установлены в главе 11 настоящего Кодекса.","article_title":"Статья 157. Последствия неявки в судебное заседание экспертов, свидетелей, переводчиков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d8d400f1dde59d38443fa39ff5f8f29cdc24c5d0115ed49e59c7e787a3777b85"},{"code_id":"APK_RF","article_number":"158","version_date":"2002-07-24","article_text":"1. Арбитражный суд откладывает судебное разбирательство в случаях, предусмотренных настоящим Кодексом, а также в случае неявки в судебное заседание лица, участвующего в деле, если в отношении этого лица у суда отсутствуют сведения об извещении его о времени и месте судебного разбирательства.\n\nСудебное разбирательство также может быть отложено по решению председателя арбитражного суда, заместителя председателя арбитражного суда или председателя судебного состава в случае болезни судьи или по иным причинам невозможности проведения судебного заседания на срок, не превышающий одного месяца. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ) (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n10. Судебное разбирательство в новом судебном заседании возобновляется с того момента, с которого оно было отложено. Повторное рассмотрение доказательств, исследованных до отложения судебного разбирательства, не производится.","article_title":"Статья 158. Отложение судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"76dfdec1b4fb46344dd1c16cf7f019876246e193ec0a28d1d3dfb27134239244"},{"code_id":"APK_RF","article_number":"16","version_date":"2002-07-24","article_text":"1. Вступившие в законную силу судебные акты арбитражного суда являются обязательными для органов государственной власти, органов местного самоуправления, иных органов, организаций, должностных лиц и граждан и подлежат исполнению на всей территории Российской Федерации.\n\nТребования арбитражного суда о представлении доказательств, сведений и других материалов, даче объяснений, разъяснений, заключений и иные требования, связанные с рассматриваемым делом, являются также обязательными и подлежат исполнению органами, организациями и лицами, которым они адресованы.\n\n11. Специализированный арбитражный суд в целях получения разъяснений, консультаций и выяснения профессионального мнения ученых, специалистов и прочих лиц, обладающих теоретическими и практическими познаниями по существу разрешаемого специализированным арбитражным судом спора, может также направлять запросы.\n\nЗапросы о даче разъяснений, консультаций и об изложении профессиональных мнений по рассматриваемым специализированным арбитражным судом делам обязательны для всех органов, организаций и лиц, которым они адресованы.\n\nЗапросы должны быть рассмотрены и ответ по результатам их рассмотрения должен быть направлен в специализированный арбитражный суд в течение месяца со дня получения этих запросов, если иной срок не указан специализированным арбитражным судом.\n\n(Дополнение частью - Федеральный закон от 08.12.2011 № 422-ФЗ)\n\n2. Неисполнение судебных актов, а также невыполнение требований арбитражных судов влечет за собой ответственность, установленную настоящим Кодексом и другими федеральными законами.\n\n3. Обязательность судебных актов не лишает лиц, не участвовавших в деле, возможности обратиться в арбитражный суд за защитой нарушенных этими актами их прав и законных интересов путем обжалования указанных актов.\n\n4. Признание и обязательность исполнения на территории Российской Федерации судебных актов, принятых иностранными судами, иностранных арбитражных решений определяются международным договором Российской Федерации, федеральным законом.","article_title":"Статья 16. Обязательность судебных актов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cee55c5c6421b2e0f130feb218c533fc67f6afcc1a9f722830bf7a87d5248fb4"},{"code_id":"APK_RF","article_number":"160","version_date":"2002-07-24","article_text":"1. В случае, если в одном заявлении соединены требование об установлении оснований ответственности ответчика и связанное с ним требование о применении мер ответственности, арбитражный суд вправе с согласия сторон рассмотреть такие требования в раздельных судебных заседаниях.\n\nО рассмотрении дела в раздельных судебных заседаниях выносится определение.\n\n2. При отказе в удовлетворении требования об установлении оснований ответственности ответчика арбитражный суд не рассматривает связанное с ним требование о применении мер ответственности и второе судебное заседание не проводит.\n\n3. В случае удовлетворения требования об установлении оснований ответственности ответчика арбитражный суд сразу же или после перерыва, срок которого не может превышать пять дней, вправе провести второе судебное заседание и в этом судебном заседании рассмотреть требование о применении мер ответственности, в том числе определить размер взыскиваемой суммы. По результатам рассмотрения арбитражный суд принимает решение по всем заявленным требованиям.\n\n4. В случае, если в судебном заседании объявлялся перерыв, во время которого стороны достигли договоренности или урегулировали спор в части требований о применении мер ответственности, арбитражный суд не рассматривает эти требования и прекращает производство по делу в части требований о применении мер ответственности при условии, что истец обратился с отказом в письменной форме от иска или стороны заключили мировое соглашение в этой части требований и отказ принят либо мировое соглашение утверждено судом, на что указывается в судебном акте арбитражного суда.","article_title":"Статья 160. Рассмотрение дела в раздельных заседаниях арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6bb0c5926f132a9f17b3b60e3792ec3d39ff6a423f8e0d23716dc563be2eb7b6"},{"code_id":"APK_RF","article_number":"161","version_date":"2002-07-24","article_text":"1. Если лицо, участвующее в деле, обратится в арбитражный суд с заявлением в письменной форме о фальсификации доказательства, представленного другим лицом, участвующим в деле, суд:\n\n1) разъясняет уголовно-правовые последствия такого заявления;\n\n2) исключает оспариваемое доказательство с согласия лица, его представившего, из числа доказательств по делу;\n\n3) проверяет обоснованность заявления о фальсификации доказательства, если лицо, представившее это доказательство, заявило возражения относительно его исключения из числа доказательств по делу.\n\nВ этом случае арбитражный суд принимает предусмотренные федеральным законом меры для проверки достоверности заявления о фальсификации доказательства, в том числе назначает экспертизу, истребует другие доказательства или принимает иные меры.\n\n2. Результаты рассмотрения заявления о фальсификации доказательства арбитражный суд отражает в протоколе судебного заседания.","article_title":"Статья 161. Заявление о фальсификации доказательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4e17eccc811950c52c43a5697ba492a123f0d37db03582f94c168cbc9792d6c"},{"code_id":"APK_RF","article_number":"163","version_date":"2002-07-24","article_text":"1. Арбитражный суд по ходатайству лица, участвующего в деле, или по своей инициативе может объявить перерыв в судебном заседании.\n\n2. Перерыв в судебном заседании может быть объявлен на срок, не превышающий десяти дней. (В редакции  Федерального закона\n\n3. На перерыв в пределах дня судебного заседания и время, когда заседание будет продолжено, указывается в протоколе судебного заседания.\n\nО перерыве на более длительный срок арбитражный суд выносит определение, которое заносится в протокол судебного заседания. В определении указываются время и место продолжения судебного заседания.\n\n4. После окончания перерыва судебное заседание продолжается, о чем объявляет председательствующий в судебном заседании. Повторное рассмотрение исследованных до перерыва доказательств не производится, в том числе при замене представителей лиц, участвующих в деле.\n\n5. Лица, участвующие в деле и присутствовавшие в зале судебного заседания до объявления перерыва, считаются надлежащим образом извещенными о времени и месте судебного заседания, и их неявка в судебное заседание после окончания перерыва не является препятствием для его продолжения.","article_title":"Статья 163. Перерыв в судебном заседании","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a5105f88c84d06170ea127a0c947e4202a30519d3713b06efd2fbb1787591b1a"},{"code_id":"APK_RF","article_number":"164","version_date":"2002-07-24","article_text":"1. После завершения исследования всех доказательств председательствующий в судебном заседании выясняет у лиц, участвующих в деле, не желают ли они чем-либо дополнить материалы дела. При отсутствии таких заявлений председательствующий в судебном заседании объявляет исследование доказательств законченным и суд переходит к судебным прениям.\n\n2. Судебные прения состоят из устных выступлений лиц, участвующих в деле, и их представителей. В этих выступлениях они обосновывают свою позицию по делу.\n\n3. В судебных прениях первыми выступают истец и (или) его представитель, затем - третье лицо, заявляющее самостоятельные требования относительно предмета спора, ответчик и (или) его представитель. Третье лицо, не заявляющее самостоятельных требований относительно предмета спора, выступает после истца или после ответчика, на стороне которого оно участвует в деле.\n\nПрокурор, представитель государственного органа, органа местного самоуправления и иного органа, обратившиеся в арбитражный суд в соответствии со статьями 52 и 53 настоящего Кодекса, выступают в судебных прениях первыми.\n\n4. Участники судебных прений не вправе ссылаться на обстоятельства, которые судом не выяснялись, и на доказательства, которые не исследовались в судебном заседании или признаны судом недопустимыми.\n\n5. После выступления всех участников судебных прений каждый из них вправе выступить с репликами. Право последней реплики всегда принадлежит ответчику и (или) его представителю.","article_title":"Статья 164. Судебные прения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1de894768f93f93cc7a138c2afcb60cb3c286bbeeb2259325b19e9d6a3b70c84"},{"code_id":"APK_RF","article_number":"165","version_date":"2002-07-24","article_text":"1. В случае, если арбитражный суд во время или после судебных прений признает необходимым выяснить дополнительные обстоятельства или исследовать новые доказательства, суд возобновляет исследование доказательств, на что указывает в протоколе судебного заседания.\n\n2. После окончания дополнительного исследования доказательств судебные прения происходят в общем порядке, установленном настоящим Кодексом.","article_title":"Статья 165. Возобновление исследования доказательств","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5aa2c41238dbb83912e7731f943b0fc6d53d6f9e5ba05738eac7eb3199ea1f2e"},{"code_id":"APK_RF","article_number":"166","version_date":"2002-07-24","article_text":"После исследования доказательств по делу и судебных прений председательствующий в судебном заседании объявляет рассмотрение дела по существу законченным и арбитражный суд удаляется для принятия решения, о чем объявляется присутствующим в зале судебного заседания.","article_title":"Статья 166. Окончание рассмотрения дела по существу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"acf8ab22b4a43a8da6cfa28efb3a474615065a479ebcdb323672e43f1a725fdd"},{"code_id":"APK_RF","article_number":"167","version_date":"2002-07-24","article_text":"1. При разрешении спора по существу арбитражный суд первой инстанции принимает решение. Решение принимается именем Российской Федерации.\n\n2. Арбитражный суд может принять отдельное решение по каждому из требований, объединенных в одном деле.\n\n3. Решение принимается судьями, участвующими в судебном заседании, в условиях, обеспечивающих тайну совещания судей.\n\n4. В помещении, в котором арбитражный суд проводит совещание и принимает судебный акт, могут находиться только лица, входящие в состав суда, рассматривающего дело. Запрещается доступ в это помещение других лиц, а также иные способы общения с лицами, входящими в состав суда.","article_title":"Статья 167. Принятие решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b8c7b2bd2be9791465d865120685f6bf57628cdc31bc4bcdae9760d37e0ce3c"},{"code_id":"APK_RF","article_number":"168","version_date":"2002-07-24","article_text":"1. При принятии решения арбитражный суд оценивает доказательства и доводы, приведенные лицами, участвующими в деле, в обоснование своих требований и возражений; определяет, какие обстоятельства, имеющие значение для дела, установлены и какие обстоятельства не установлены, какие законы и иные нормативные правовые акты следует применить по данному делу; устанавливает права и обязанности лиц, участвующих в деле; решает, подлежит ли иск удовлетворению.\n\n2. При принятии решения арбитражный суд решает вопросы о сохранении действия мер по обеспечению иска или об отмене обеспечения иска либо об обеспечении исполнения решения; при необходимости устанавливает порядок и срок исполнения решения; определяет дальнейшую судьбу вещественных доказательств, распределяет судебные расходы, а также решает иные вопросы, возникшие в ходе судебного разбирательства.\n\n3. Арбитражный суд, признав при принятии решения необходимым дополнительно исследовать доказательства или продолжить выяснение обстоятельств, имеющих значение для дела, возобновляет судебное разбирательство, о чем выносит определение.","article_title":"Статья 168. Вопросы, разрешаемые при принятии решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb26b15d73308774d5af9fadd8196f9e35097e2081b64605159af5ff40c0eb3c"},{"code_id":"APK_RF","article_number":"169","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда излагается в виде отдельного документа.\n\nРешение выполняется в форме электронного документа. При отсутствии в арбитражном суде технической возможности для выполнения решения в форме электронного документа решение выполняется на бумажном носителе.\n\n(Часть в редакции Федерального закона от 23.06.2016 № 220-ФЗ)\n\n2. В решении должны быть указаны мотивы его принятия, и оно должно быть изложено языком, понятным для лиц, участвующих в деле, и других лиц.\n\n3. Решение подписывается судьей, а в случае коллегиального рассмотрения дела - всеми судьями, участвовавшими в принятии решения, в том числе судьей, имеющим особое мнение.\n\n4. Исправления в решении должны быть оговорены и удостоверены подписями всех судей в совещательной комнате до объявления решения.","article_title":"Статья 169. Изложение решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6e5cdfb2e7c4303287eebb7d80ea583972ef11b6ae04f674f918dac6cdc4d6e5"},{"code_id":"APK_RF","article_number":"17","version_date":"2002-07-24","article_text":"1. Дела в первой инстанции арбитражного суда рассматриваются судьей единолично, если коллегиальное рассмотрение дела не предусмотрено настоящей статьей. Коллегиальное рассмотрение дел в арбитражном суде первой инстанции осуществляется в составе трех судей или судьи и двух арбитражных заседателей.\n\n2. В первой инстанции арбитражного суда коллегиальным составом судей рассматриваются:\n\n1) (Пункт утратил силу - Федеральный закон от 28.06.2014 № 186-ФЗ)\n\n2) дела об оспаривании нормативных правовых актов;\n\n3) (Пункт утратил силу - Федеральный закон от 12.07.2011 № 210-ФЗ)\n\n4) дела, направленные в арбитражный суд первой инстанции на новое рассмотрение с указанием на коллегиальное рассмотрение;\n\n5) дела, решения о коллегиальном рассмотрении которых приняты председателем судебного состава в связи с их особой сложностью на основании мотивированного заявления судьи; (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n6) дела, относящиеся к подсудности Суда по интеллектуальным правам. (Дополнение пунктом - Федеральный закон от 08.12.2011 № 422-ФЗ)\n\n3. Арбитражный суд первой инстанции в составе судьи и двух арбитражных заседателей рассматривает экономические споры и иные дела, возникающие из гражданских и иных правоотношений, если какая-либо из сторон заявит ходатайство о рассмотрении дела с участием арбитражных заседателей.\n\nНе подлежат рассмотрению с участием арбитражных заседателей дела, предусмотренные частью 2 настоящей статьи, а также дела, возникающие из административных и иных публичных правоотношений, и дела особого производства.\n\n4. Дела в арбитражном суде апелляционной и кассационной инстанций, а также в порядке надзора рассматриваются коллегиально в составе трех или иного нечетного количества судей, если иное не установлено настоящим Кодексом.\n\nПри коллегиальном рассмотрении дела один из судей председательствует в судебном заседании.\n\n5. В случае, если настоящим Кодексом судье предоставлено право единолично рассматривать дела и разрешать отдельные процессуальные вопросы, судья действует от имени арбитражного суда.","article_title":"Статья 17. Единоличное и коллегиальное рассмотрение дел","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e90baa7722ef0beb1bb3b359abb162c4d52e076a5c1788afb711978a50a3cc21"},{"code_id":"APK_RF","article_number":"170","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда должно состоять из вводной, описательной, мотивировочной и резолютивной частей.\n\n2. Вводная часть решения должна содержать наименование арбитражного суда, принявшего решение; состав суда, фамилию лица, которое вело протокол судебного заседания; номер дела, дату и место принятия решения; предмет спора; наименования лиц, участвующих в деле, фамилии лиц, присутствовавших в судебном заседании, с указанием их полномочий.\n\n3. Описательная часть решения должна содержать краткое изложение заявленных требований и возражений, объяснений, заявлений и ходатайств лиц, участвующих в деле.\n\n4. В мотивировочной части решения должны быть указаны:\n\n1) фактические и иные обстоятельства дела, установленные арбитражным судом;\n\n2) доказательства, на которых основаны выводы суда об обстоятельствах дела и доводы в пользу принятого решения; мотивы, по которым суд отверг те или иные доказательства, принял или отклонил приведенные в обоснование своих требований и возражений доводы лиц, участвующих в деле;\n\n3) законы и иные нормативные правовые акты, которыми руководствовался суд при принятии решения, и мотивы, по которым суд не применил законы и иные нормативные правовые акты, на которые ссылались лица, участвующие в деле.\n\nВ мотивировочной части решения должны содержаться также обоснования принятых судом решений и обоснования по другим вопросам, указанным в части 5 настоящей статьи.\n\nВ случае признания иска ответчиком в мотивировочной части решения может быть указано только на признание иска и принятие его судом.\n\nВ случае отказа в иске в связи с признанием неуважительными причин пропуска срока исковой давности или срока обращения в суд в мотивировочной части решения суда указывается только на установление судом данных обстоятельств.\n\nВ мотивировочной части решения могут содержаться ссылки на постановления Пленума Верховного Суда Российской Федерации и сохранившие силу постановления Пленума Высшего Арбитражного Суда Российской Федерации по вопросам судебной практики, на постановления Президиума Верховного Суда Российской Федерации и сохранившие силу постановления Президиума Высшего Арбитражного Суда Российской Федерации, а также на обзоры судебной практики Верховного Суда Российской Федерации, утвержденные Президиумом Верховного Суда Российской Федерации.\n\n(Часть в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nПри полном или частичном удовлетворении первоначального и встречного исков в резолютивной части решения указывается денежная сумма, подлежащая взысканию в результате зачета.\n\nЕсли арбитражный суд установил порядок исполнения решения или принял меры по обеспечению его исполнения, на это указывается в резолютивной части решения.","article_title":"Статья 170. Содержание решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11b84412950acdc75ecbd7612b4564c0f87fecf83cab11f770c00b76e390f336"},{"code_id":"APK_RF","article_number":"171","version_date":"2002-07-24","article_text":"1. При удовлетворении требования о взыскании денежных средств в резолютивной части решения арбитражный суд указывает общий размер подлежащих взысканию денежных сумм с раздельным определением основной задолженности, убытков, неустойки (штрафа, пеней) и процентов.\n\n2. При присуждении имущества арбитражный суд указывает наименование имущества, подлежащего передаче истцу, его стоимость и место нахождения.","article_title":"Статья 171. Решение о взыскании денежных средств и присуждении имущества","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cffde025f93253e972299cf36b7959e22ef3bc73f66ffb8b0471e38f9c693c85"},{"code_id":"APK_RF","article_number":"172","version_date":"2002-07-24","article_text":"При удовлетворении требования относительно спора о признании не подлежащим исполнению исполнительного или иного документа, по которому взыскание производится в бесспорном (безакцептном) порядке, в том числе на основании исполнительной надписи нотариуса, в резолютивной части решения арбитражный суд указывает наименование, номер, дату выдачи документа, не подлежащего исполнению, и денежную сумму, не подлежащую списанию.","article_title":"Статья 172. Решение о признании не подлежащим исполнению исполнительного или иного документа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad4ef4ad5ee013285735b937e4040514a420f538b5b079a5f0f26f936092a5ce"},{"code_id":"APK_RF","article_number":"173","version_date":"2002-07-24","article_text":"По спору, возникшему при заключении или изменении договора, в резолютивной части решения указывается вывод арбитражного суда по каждому спорному условию договора, а по спору о понуждении заключить договор указываются условия, на которых стороны обязаны заключить договор.","article_title":"Статья 173. Решение о заключении или об изменении договора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c1fad081c2def206fc15796f0f83f010825ceab9df5275f21d8894a8e521556"},{"code_id":"APK_RF","article_number":"174","version_date":"2002-07-24","article_text":"1. При принятии решения, обязывающего ответчика совершить определенные действия, не связанные со взысканием денежных средств или с передачей имущества, арбитражный суд в резолютивной части решения указывает лицо, обязанное совершить эти действия, а также место и срок их совершения.\n\n2. При принятии решения, обязывающего организацию совершить определенные действия, не связанные со взысканием денежных средств или с передачей имущества, арбитражный суд в резолютивной части решения может указать руководителя или иное лицо, на которых возлагается исполнение решения, а также срок исполнения.\n\n3. Арбитражный суд может указать в решении, что истец вправе осуществить соответствующие действия за счет ответчика со взысканием с него необходимых расходов в случае, если ответчик не исполнит решение в течение установленного срока.","article_title":"Статья 174. Решение, обязывающее ответчика совершить определенные действия","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"389d2d8778f75e1f71373a78b6adddc0447baee9e6c922a946bfc3ce0651aa82"},{"code_id":"APK_RF","article_number":"175","version_date":"2002-07-24","article_text":"1. При принятии решения в пользу нескольких истцов арбитражный суд указывает, в какой части (доле) оно относится к каждому из них, или указывает, что право требования является солидарным.\n\n2. При принятии решения против нескольких ответчиков арбитражный суд указывает, в какой части (доле) каждый из ответчиков должен выполнить решение, или указывает, что их ответственность является солидарной.","article_title":"Статья 175. Решение в пользу нескольких истцов или против нескольких ответчиков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b3b9a6e8651fe7ac60d967958e7991ff6748f9aaf42e22c94e4aa39fd265ca99"},{"code_id":"APK_RF","article_number":"176","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда объявляется председательствующим в том судебном заседании, в котором закончено рассмотрение дела по существу, после принятия решения арбитражного суда.\n\n2. В судебном заседании, в котором закончено рассмотрение дела по существу, может быть объявлена только резолютивная часть принятого решения. В этом случае арбитражный суд объявляет, когда будет изготовлено решение в полном объеме и разъясняет порядок доведения его до сведения лиц, участвующих в деле.\n\nИзготовление решения в полном объеме может быть отложено на срок, не превышающий десяти дней. Дата изготовления решения в полном объеме считается датой принятия решения. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n3. Объявленная резолютивная часть решения должна быть подписана всеми судьями, участвовавшими в рассмотрении дела и принятии решения, и приобщена к делу.\n\nПри выполнении резолютивной части решения в форме электронного документа дополнительно выполняется экземпляр данной резолютивной части решения на бумажном носителе, который также приобщается к делу. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n4. Председательствующий в судебном заседании после объявления решения разъясняет порядок его обжалования.","article_title":"Статья 176. Объявление решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2c64f4f2fe285eb406fbb6e5391387cb5c03d0f14fb8eb57b8b9371a36d80f2"},{"code_id":"APK_RF","article_number":"177","version_date":"2002-07-24","article_text":"1. Решение, выполненное в форме электронного документа, направляется лицам, участвующим в деле, посредством его размещения в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" в режиме ограниченного доступа не позднее следующего дня после дня его принятия.\n\nРешение, выполненное в форме электронного документа, может быть также направлено лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия.\n\nПо ходатайству указанных лиц копии решения на бумажном носителе могут быть направлены им в пятидневный срок со дня поступления соответствующего ходатайства в арбитражный суд заказным письмом с уведомлением о вручении или вручены им под расписку.\n\nВ случае, если решение выполнено только на бумажном носителе, арбитражный суд направляет копии решения лицам, участвующим в деле, в пятидневный срок со дня принятия решения заказным письмом с уведомлением о вручении или вручает им под расписку.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В случаях и в порядке, которые предусмотрены настоящим Кодексом, арбитражный суд направляет копии решения и иным лицам.\n\n3. Повторная выдача копий решения и других судебных актов лицам, участвующим в деле, оплачивается государственной пошлиной.","article_title":"Статья 177. Направление решения лицам, участвующим в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb9f05bd05903f457040387b68b7dbbc9198b64c026d83321e6bebb32453aa4d"},{"code_id":"APK_RF","article_number":"178","version_date":"2002-07-24","article_text":"1. Арбитражный суд, принявший решение, до вступления этого решения в законную силу по своей инициативе или по заявлению лица, участвующего в деле, вправе принять дополнительное решение в случае, если:\n\n1) по какому-либо требованию, в отношении которого лица, участвующие в деле, представили доказательства, судом не было принято решение;\n\n2) суд, разрешив вопрос о праве, не указал в решении размер присужденной денежной суммы, подлежащее передаче имущество или не указал действия, которые обязан совершить ответчик;\n\n3) судом не разрешен вопрос о судебных расходах.\n\n2. Вопрос о принятии арбитражным судом дополнительного решения разрешается в судебном заседании. Лица, участвующие в деле, извещаются о времени и месте судебного заседания. Неявка надлежащим образом извещенных лиц не препятствует рассмотрению вопроса о принятии дополнительного решения.\n\n3. Дополнительное решение принимается по правилам, установленным в настоящей главе.\n\n4. В случае отказа в принятии дополнительного решения выносится определение.\n\n5. Дополнительное решение арбитражного суда и определение арбитражного суда об отказе в принятии дополнительного решения могут быть обжалованы.","article_title":"Статья 178. Дополнительное решение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24d16dd8487eb02d8091a6312d3f2580a7959c187e96000755fa4f9eae1b7616"},{"code_id":"APK_RF","article_number":"179","version_date":"2002-07-24","article_text":"1. В случае неясности решения арбитражный суд, принявший это решение, по заявлению лица, участвующего в деле, судебного пристава-исполнителя, других исполняющих решение арбитражного суда органа, организации вправе разъяснить решение без изменения его содержания.\n\n2. Разъяснение решения допускается, если оно не приведено в исполнение и не истек срок, в течение которого решение может быть принудительно исполнено.\n\n3. Арбитражный суд, принявший решение, по заявлению лица, участвующего в деле, судебного пристава-исполнителя, других исполняющих решение арбитражного суда органа, организации или по своей инициативе вправе исправить допущенные в решении описки, опечатки и арифметические ошибки без изменения его содержания.","article_title":"Статья 179. Разъяснение решения. Исправление описок, опечаток и арифметических ошибок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"06cfafe55c4d5c1bce7f9682b77241e5f860798d474746bfd080e708ce8b62e6"},{"code_id":"APK_RF","article_number":"18","version_date":"2002-07-24","article_text":"1) заявленного и удовлетворенного в порядке, установленном настоящим Кодексом, самоотвода или отвода судьи, арбитражного заседателя;\n\n2) длительного отсутствия судьи, арбитражного заседателя ввиду болезни, отпуска, пребывания на учебе, нахождения в служебной командировке.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 18. Формирование состава суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f22af3542bac4229a7b8375dff4f041426c51e1b21df47ed6b63ff02452cf1b9"},{"code_id":"APK_RF","article_number":"180","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n1. Решение арбитражного суда первой инстанции, за исключением решений, указанных в частях 2 и 3 настоящей статьи, вступает в законную силу по истечении месячного срока со дня его принятия, если не подана апелляционная жалоба. В случае подачи апелляционной жалобы решение, если оно не отменено и не изменено, вступает в законную силу со дня принятия постановления арбитражного суда апелляционной инстанции.","article_title":"Статья 180. Вступление в законную силу решения, судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdfeed76172280c8e02c26e1c3afa125b25ae5087ff01cc110ed664e8fbf014d"},{"code_id":"APK_RF","article_number":"181","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 181. Обжалование решения арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0dcb8aa602e92c57e5152bcb95c6af95dbb96cc7240b502c878aacb65ed6813c"},{"code_id":"APK_RF","article_number":"182","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n1. Решение арбитражного суда приводится в исполнение после вступления его в законную силу, за исключением случаев немедленного исполнения, в порядке, установленном настоящим Кодексом и иными федеральными законами, регулирующими вопросы исполнительного производства.\n\nКопии определения направляются лицам, участвующим в деле, не позднее следующего дня после дня его вынесения.","article_title":"Статья 182. Исполнение решения, судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8a97fbb5924a665e6172ad474d06ecd777e77361b53cbf8ccd6463f605a9777"},{"code_id":"APK_RF","article_number":"183","version_date":"2002-07-24","article_text":"1. По заявлению взыскателя или должника арбитражный суд первой инстанции, рассмотревший дело, производит индексацию присужденных судом денежных сумм на день исполнения решения суда.\n\nЕсли иное не предусмотрено федеральным законом, присужденные денежные суммы индексируются со дня вынесения решения суда или, если решением суда предусмотрена выплата присужденной денежной суммы в предстоящем периоде, с момента, когда такая выплата должна была быть произведена.\n\nЕсли иное не предусмотрено федеральным законом или договором, для индексации используется официальная статистическая информация об индексе потребительских цен (тарифов) на товары и услуги в Российской Федерации, размещаемая на официальном сайте федерального органа исполнительной власти, осуществляющего функции по формированию официальной статистической информации о социальных, экономических, демографических, экологических и других общественных процессах в Российской Федерации, в информационно-телекоммуникационной сети \"Интернет\".\n\nЗаявление об индексации присужденных судом денежных сумм может быть подано в срок, не превышающий одного года со дня исполнения должником судебного акта. При наличии уважительных причин указанный срок может быть восстановлен арбитражным судом в порядке, предусмотренном статьей 117 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 01.04.2025 № 54-ФЗ)\n\n(Часть в редакции Федерального закона от 11.06.2022 № 177-ФЗ)\n\nПо результатам рассмотрения заявления выносится определение.","article_title":"Статья 183. Индексация присужденных денежных сумм","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a74c81ef6fc8e25030e49acd98ddb20aa1435b8df238680667d5bc4d27f8b3a"}]$law7v001$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
